(window.TN_SEARCH_SHARD=window.TN_SEARCH_SHARD||{})["desktop-gui"]=[{"u":"desktop-gui/desktop_gui_study_path.html","t":"桌面 GUI 与 Qt 学习路径","c":"桌面 GUI / Qt","s":[{"a":"","h":"","x":"桌面 GUI 与 Qt 学习路径 · Study Path Kavin Tech Notes ← 主页 目录 ◐ 桌面 GUI · 学习路径 P0 · 零基础入门 P1 · 对象模型与线程 P2 · 通信与交付 Desktop GUI · Study Path 桌面 GUI 与 Qt 学习路径 P0 零基础入门 ：Qt 是什么、关键模块、第一个程序与项目分层 → P1 对象模型与线程 ：QObject 对象树、信号槽与 moc、QThread 与跨线程通信 → P2 通信与交付 ：网络与本机 IPC、构建部署与陷阱清单。适合有 C++ 基础、要做工业上位机或仪器软件的工程师； 完全没接触过 Qt 的人从 P0 开始 。 ~17 h 前置：C++ 基础 · CMake"},{"a":"ch1","h":"","x":"P0 零基础入门（~3 h） # 内容 时间 重点 0 Qt 零基础全景入门 1.5 h Qt 是什么、模块地图、Hello World 逐行、moc/uic/rcc 0′ 动手：装 Qt Creator，敲出计数器窗口并用 Designer 拖一个界面 1.5 h 能建工程、能打断点、能看懂生成的 ui_*.h ✅ 阶段检查 能解释 show() 为什么不画界面、 exec() 到底在做什么 能说出手上项目要链哪几个 Qt 模块，以及为什么不需要其他模块 看到 undefined reference to vtable 能立刻想到 moc，而不是去搜链接器参数 能给出「本项目选 Widgets 还是 QML」的初步结论与依据 P1 对象模型与线程（~7 h） # 内容 时间 重点 1 Qt 核心机制 3.5 h 对象树所有权、moc 如何实现信号槽、事件循环 2 Qt 线程与并发 3.5 h moveToThread 而非继承 QThread、连接类型在 emit 时决定 ✅ 阶段检查 能说清「谁负责 delete」：父子树、栈对象、智能指针三者为什么不能混用 能画出 emit 到槽执行之间的完整链路，并解释 Queued 连接的参数是怎么传过去的 能指出「QThread 子类的槽跑在哪个线程」这个经典误区错在哪 P2 通信与交付（~7 h） # 内容 时间 重点 3 Qt 网络与本机 IPC 3.5 h 粘包半包处理、TLS 证书校验、设备重连状态机 4 Qt 工程化与陷阱 3.5 h AUTOMOC、Widgets/QML 选型、模型视图性能、部署清单 ~17 h ✅ 完成标志 能独立写出一个带长度前缀的 TCP 收包循环，并说明如何防御超大长度字段 能设计一个带指数退避与心跳的设备重连状态机，说清每个状态的进入与退出条件 能解释 undefined reference to vtable 与「找不到平台插件」两类错误的根因 能就「这个项目用 Widgets 还是 QML」给出有理有据的选型结论 ← 目录 C++ 路径 系统编程路径 全站路径"}]},{"u":"desktop-gui/qt_engineering.html","t":"Qt 工程化与陷阱完全指南","c":"桌面 GUI / Qt","s":[{"a":"","h":"","x":"Qt 工程化与陷阱完全指南 · CMake+AUTOMOC / Widgets vs QML / 模型视图性能 / D-Pointer 与 ABI / 部署 Kavin Tech Notes ← 主页 目录 25 min ◐ Qt 工程化 CMake + AUTOMOC 构建 Widgets 与 QML 选型 模型视图与大数据量 图像显示的性能路径 D-Pointer 与 ABI 治理 部署与打包 高 DPI · i18n · 样式 陷阱总清单 面试题集（12 道） 9.1 基础 9.2 中级 9.3 高级 Desktop GUI · Qt Engineering · 2026 Qt 工程化与陷阱完全指南 会写 Qt 代码和能交付一个 Qt 产品之间隔着一整套工程问题： 构建脚本怎么写才不会每次全量重编 、 Widgets 还是 QML 、 十万行表格为什么卡 、 换个 Qt 小版本为什么客户现场就崩 、 打包漏了哪个插件导致「本机好好的，装到客户机就白屏」 。本篇把这些一次讲清，配一个虚拟滚动的可交互演示。 核心难度 ★★★★☆ 交付必备 阅读时长 ~25 min 前置 Qt 核心机制 · CMake CMake · AUTOMOC Widgets vs QML 模型视图性能 D-Pointer · 部署 没写过 Qt？ 先读 Qt 零基础全景入门 （含 moc / uic / rcc 构建链与最小 CMake 工程），本篇在此基础上讲选型、性能与部署交付。"},{"a":"s1","h":"CMake + AUTOMOC 构建","x":"01 CMake + AUTOMOC 构建 Qt6 之后的唯一正解 AUTOMOC / AUTOUIC / AUTORCC ：CMake 的三个开关，让它自动帮你跑 Qt 的三个代码生成器—— moc （处理 Q_OBJECT ）、 uic （把 Designer 的 .ui 转成头文件）、 rcc （把资源打进二进制）。开了之后你不需要在 CMakeLists 里手写任何生成规则。 cmake_minimum_required (VERSION 3.21) project (vision_inspector LANGUAGES CXX) # Qt6 强制 C++17；用 20 也可以 set (CMAKE_CXX_STANDARD 17) set (CMAKE_CXX_STANDARD_REQUIRED ON) # 三个自动化开关（Qt6 也可用 qt_standard_project_setup() 一次性打开） set (CMAKE_AUTOMOC ON) set (CMAKE_AUTOUIC ON) set (CMAKE_AUTORCC ON) # 同时支持 Qt5 / Qt6 的写法 find_package (QT NAMES Qt6 Qt5 REQUIRED COMPONENTS Widgets Network Concurrent) find_package (Qt ${QT_VERSION_MAJOR} REQUIRED COMPONENTS Widgets Network Concurrent) qt_add_executable (vision_inspector # Qt6 的封装，会处理部署相关的额外步骤 src/main.cpp src/mainwindow.cpp src/mainwindow.h src/mainwindow.ui resources/app.qrc ) target_link_libraries (vision_inspector PRIVATE Qt ${QT_VERSION_MAJOR} ::Widgets Qt ${QT_VERSION_MAJOR} ::Network Qt ${QT_VERSION_MAJOR} ::Concurrent ) # Windows 下不弹控制台；macOS 生成 .app set_target_properties (vision_inspector PROPERTIES WIN32_EXECUTABLE ON MACOSX_BUNDLE ON ) 问题 原因 处理 undefined reference to vtable for X 加了 Q_OBJECT 但 moc 没跑（头文件不在 target 的源文件列表里） 把 .h 也列进 qt_add_executable ，AUTOMOC 只扫描 target 里列出的文件 改一个头文件全项目重编 公共头文件里塞了太多东西 / 没用 PIMPL 见 §5；另外 CMAKE_UNITY_BUILD 与 ccache 都能显著提速 moc 生成的文件找不到 CMAKE_INCLUDE_CURRENT_DIR 没开（Qt5 时代常见） Qt6 的 qt_add_executable 已处理；Qt5 手动 set(CMAKE_INCLUDE_CURRENT_DIR ON) 把 moc_x.cpp 手动 #include 进 cpp 老代码遗留习惯 用 AUTOMOC 后 不要 再手动 include，会重复定义。例外：类定义写在 .cpp 里时，末尾要 #include \"x.moc\" 为什么把类定义写在 .cpp 里就要手动 #include \"x.moc\" ？ 因为 AUTOMOC 对头文件生成的是 moc_x.cpp （自动加入构建），对源文件里发现的 Q_OBJECT 生成的是 x.moc （ 不会 自动加入构建，需要你在该 cpp 末尾 include）。这是 Qt 构建里最容易卡住新人半小时的一个规则。CMake 本身的现代写法见 Modern CMake 深入 。 qmake 不要在新项目里用了。 Qt6 官方主推 CMake，qmake 仅保留兼容且已停止演进。存量 .pro 项目迁移时注意： SOURCES/HEADERS/FORMS 直接映射到 qt_add_executable 的文件列表； QT += widgets network 映射到 find_package 的 COMPONENTS 与 target_link_libraries ； DEFINES 映射到 target_compile_definitions 。真正麻烦的是自定义的 QMAKE_EXTRA_COMPILERS ，要改写成 add_custom_command 。"},{"a":"s2","h":"Widgets 与 QML 选型","x":"02 Widgets 与 QML 选型 一个影响三年的决定 Widgets 像 装修好的标准间 ：桌椅床柜都是现成的，摆一摆就能住，风格跟着酒店（操作系统）走。QML 像 毛坯 loft + 设计师 ：想做什么造型都行，动效随便加，但家具得自己设计，而且要通水电（GPU 驱动）。 Qt Widgets 渲染路径 QWidget::paintEvent(QPainter) QBackingStore（CPU 光栅化到位图） 整块位图交给窗口系统 全程在 GUI 线程 · CPU 绘制 优点：确定性强、无 GPU 依赖、原生外观 短板：复杂动效吃 CPU Qt Quick / QML 渲染路径 QML 声明式描述 → 场景图 (Scene Graph) 渲染线程：合批 · 剔除 · 生成绘制调用 RHI → Vulkan / Metal / D3D / OpenGL 渲染在独立线程 · GPU 合成 优点：动效流畅、UI 线程更空闲 短板：依赖显卡驱动，工控机上是风险 本质差异：Widgets 是 CPU 光栅化 + 单线程；Quick 是 GPU 场景图 + 独立渲染线程 维度 Qt Widgets Qt Quick / QML 典型场景 工业软件、仪器上位机、CAD、数据密集型表单 车机 HMI、触摸屏、移动端、动效重的产品 复杂表格 / 树 成熟 ： QTableView + 模型视图，几十万行没问题 TableView 相对年轻，复杂交互要自己补 动效 要手写 QPropertyAnimation ，做复杂了很累 一等公民 ，几行声明搞定 GPU 依赖 无（软件光栅化） 有 ——老工控机、远程桌面、虚拟机上可能降级或黑屏 与 C++ 的边界 没有边界，全是 C++ 要设计 C++ 与 QML 的接口（属性、Q_INVOKABLE、模型暴露） 调试 普通 C++ 调试 QML 侧是解释执行， 错误多在运行时才暴露 团队要求 C++ 工程师即可 需要有人熟 QML/JS，否则容易写成「JS 里塞业务逻辑」 无障碍 / 输入法 成熟 较弱 工业检测这类场景，默认选 Widgets。 三条理由值得在面试时讲出来： ① 界面主体是图像显示 + 参数表格 + 结果列表，Widgets 的模型视图体系正好对口； ② 工控机显卡驱动往往老旧，还经常通过远程桌面操作， GPU 渲染是可靠性风险而不是收益 ； ③ 团队大概率是 C++ 背景，引入 QML 等于引入第二套语言与调试链。反过来，如果产品是带触摸屏的一体机、要做酷炫动效，QML 才是对的。 两者可以混用： QQuickWidget 把 QML 场景嵌进 Widgets 窗口， QWidget::createWindowContainer 反过来嵌。但混用意味着 两套渲染路径共存 ，层叠、缩放、输入法都会有边界问题，不到必要不要开这个口子。"},{"a":"s3","h":"模型视图与大数据量","x":"03 模型视图与大数据量 十万行表格为什么卡，怎么不卡 模型/视图（Model/View） ：Qt 把「数据」与「显示」分开—— QAbstractItemModel 提供数据， QTableView / QListView / QTreeView 负责显示， QItemDelegate 负责单元格的绘制与编辑。视图 只向模型索取当前可见的那些格子 ，这就是它能扛大数据量的根本原因。 QTableWidget 像 把整本书全部打印出来铺在桌上 ——十万行就是十万个 widget 对象。 QTableView + 模型像 电子阅读器 ：书还在存储里，屏幕上只渲染当前这一页，翻到哪读到哪。 动手感受：全量渲染 vs 按需渲染 同样是 5 万行数据。「全量」会真的创建 5 万个 DOM 节点（等价于 QTableWidget 的做法），点击后能明显感到卡顿；「按需」只渲染可视区域的约 8 行（等价于 QTableView + 模型），瞬间完成。注意看创建节点数与耗时。 全量渲染 5 万行 按需渲染（虚拟滚动） 模式：按需渲染 · 已创建节点 0 · 耗时 0 ms 自定义模型的最小实现 class DefectModel : public QAbstractTableModel { Q_OBJECT public : int rowCount( const QModelIndex& p = {}) const override { return p.isValid() ? 0 : m_rows.size(); // 表格模型：父索引有效时返回 0 } int columnCount( const QModelIndex& = {}) const override { return 5 ; } QVariant data( const QModelIndex& ix, int role) const override { if (!ix.isValid()) return {}; const Defect& d = m_rows[ix.row()]; switch (role) { case Qt::DisplayRole: return displayFor(d, ix.column()); case Qt::ForegroundRole: return d.critical ? QColor(Qt::red) : QVariant{}; case Qt::UserRole: return d.id; // 给代码用的原始值 default : return {}; } } // ★ 批量追加：必须用 begin/end 包住，否则视图状态错乱 void append( const QVector<Defect>& batch) { if (batch.isEmpty()) return ; beginInsertRows({}, m_rows.size(), m_rows.size() + batch.size() - 1 ); m_rows += batch; endInsertRows(); } private : QVector<Defect> m_rows; }; 症状 根因 处理 几万行就卡到不能用 用了 QTableWidget （每格一个 widget 对象） 换 QTableView + 自定义模型 加载时 UI 冻结几秒 一次性 insertRow 几万次，每次都触发视图更新 批量 beginInsertRows 一次包住；或用 QSortFilterProxyModel 的 setDynamicSortFilter(false) 临时关排序 滚动时掉帧 data() 里做了昂贵计算（格式化、查数据库） data() 必须是 O(1) 且无 IO ；预计算好放在内存里 列宽自适应导致卡顿 resizeColumnsToContents() 要遍历 所有行 用 setSectionResizeMode(QHeaderView::Interactive) 或只按可见行估算 行高不一致时滚动条乱跳 视图需要遍历全部行算总高 setUniformRowHeights(true) （QTreeView）/ 固定行高 增量刷新后选中项丢失 用了 reset() 而不是精确的 insert/remove 信号 用 beginInsertRows / dataChanged 精确通知 data() 是性能的绝对热点。 视图每次重绘、每次滚动、每个可见格子、 每个 role 都会调它——一屏 200 个格子 × 5 个 role = 1000 次调用，每秒 60 帧就是 6 万次。在里面做字符串格式化（ QString::number 、 arg() ）都可能成为瓶颈，做数据库查询更是灾难。 规则： data() 里只能查表和返回，任何计算都提前做好。"},{"a":"s4","h":"图像显示的性能路径","x":"04 图像显示的性能路径 机器视觉上位机的核心问题 工业检测的界面主体往往是「一张几千万像素的图 + 叠加的缺陷标注 + 实时刷新」。这条路径上有三个容易踩的坑。 坑一：在 paintEvent 里缩放原图 ❌ 每帧缩放全图 void ImageView::paintEvent(QPaintEvent*) { QPainter p( this ); // 5000×4000 的图缩到 800×600，每帧都算一次 p.drawPixmap(rect(), m_pixmap); } // 20 MPix 的双线性缩放 ≈ 几十 ms， // 直接把帧率压到个位数 ✅ 缓存缩放结果 void ImageView::setImage( const QImage& img) { m_src = img; m_cacheDirty = true ; update(); } void ImageView::paintEvent(QPaintEvent*) { if (m_cacheDirty || m_cache.size() != size()) { m_cache = QPixmap::fromImage( m_src.scaled(size(), Qt::KeepAspectRatio, Qt::FastTransformation)); // 预览用快速插值 m_cacheDirty = false ; } QPainter p( this ); p.drawPixmap( 0 , 0 , m_cache); drawOverlays(p); // 标注画在缓存之上，标注变化不需要重缩放 } 坑二：QImage 与 QPixmap 用反了 QImage QPixmap 存储 纯内存位图，格式明确 可能是窗口系统资源（X11 Pixmap / GDI） 线程 可在任意线程使用 只能主线程 像素访问 bits() / scanLine() 直接改 不能直接访问 绘制到屏幕 较慢（可能要转换） 快 ，为显示优化 该用在 算法处理、跨线程传递、文件读写 最终显示那一步 正确的分工 ：工作线程全程用 QImage 做算法；通过 Queued 信号传回 UI 线程（ QImage 隐式共享，跨线程传递只是原子加引用计数，不会深拷贝几十 MB）； UI 线程再 QPixmap::fromImage() 一次并缓存 。另外要注意像素格式： QImage::Format_RGB32 / Format_ARGB32_Premultiplied 与屏幕格式一致时绘制最快，用 Format_RGB888 每次绘制都要转换。 坑三：全量重绘而不是脏区重绘 // ❌ 任何变化都重画整个控件 update(); // ✅ 只重画变化的那块 update(defectRect.adjusted(- 2 , - 2 , 2 , 2 )); // 留出边框宽度 // paintEvent 里也要利用脏区裁剪 void ImageView::paintEvent(QPaintEvent* e) { QPainter p( this ); p.setClipRegion(e->region()); // 只画需要的部分 for ( const auto & d : m_defects) if (e->region().intersects(d.rect)) // 跳过不可见的标注 drawDefect(p, d); } 性能问题不要靠猜。Qt 侧可以用 QElapsedTimer 直接量 paintEvent 耗时并打日志；系统侧用 perf 火焰图看热点函数——大多数「界面卡」最后都定位到 QImage::scaled 、 QPainter::drawText （大量小文本）或者模型的 data() 。方法论见 C++ 性能优化方法论 。"},{"a":"s5","h":"D-Pointer 与 ABI 治理","x":"05 D-Pointer 与 ABI 治理 Qt 自己怎么做到二十年不破坏 ABI D-Pointer（PIMPL） ：把类的所有数据成员搬到一个前向声明的私有实现类里，公开类只保留一个指向它的指针。 公开类的大小与内存布局从此固定 ，往实现类里增删成员不会改变 ABI，动态库可以只换 .so 不重编译调用方。 D-Pointer 像 公司前台 ：外面的人只认识前台一个人（指针），后面办公室怎么增减工位、部门怎么重组，访客完全无感。如果没有前台，每次内部调整都得给所有合作方发通知「我们的门牌号变了」——那就是 ABI 破坏。 ❌ 没有 D-Pointer：新增成员改变对象大小 v1: [ vptr | int a | double b ] sizeof = 24 v2: [ vptr | int a | double b | QString c ] = 32 调用方还按 24 字节分配 → 越界踩内存 必须整体重编译，无法只替换动态库 ✅ 有 D-Pointer：公开类大小恒定 v1: [ vptr | d_ptr ] sizeof = 16 v2: [ vptr | d_ptr ] sizeof = 16（不变） CameraPrivate 里随便加成员，外部不可见 只替换 .so 即可升级 代价：一次额外指针跳转 + 堆分配 D-Pointer 用一次间接寻址换取二进制兼容性——库要长期演进时非常划算 // camera.h —— 对外头文件，不暴露任何实现细节 class CameraPrivate; // 前向声明即可 class VISION_EXPORT Camera : public QObject { Q_OBJECT public : explicit Camera(QObject* parent = nullptr ); ~Camera() override ; // ★ 必须在 .cpp 里定义 bool open( const QString& id); private : QScopedPointer<CameraPrivate> d; // Qt 风格；std::unique_ptr 也可以 Q_DECLARE_PRIVATE(Camera) // 生成 d_func() 便捷访问 }; // camera.cpp class CameraPrivate { public : QString id; QTimer poll; int retries = 0 ; // 随便加，不影响 ABI }; Camera::Camera(QObject* p) : QObject(p), d( new CameraPrivate) {} Camera::~Camera() = default ; // 此处 CameraPrivate 已是完整类型 析构函数必须在 .cpp 里定义。 如果在头文件里写 ~Camera() = default; ，编译器会在 调用方的翻译单元 生成析构代码——而那里 CameraPrivate 只有前向声明，是不完整类型。 unique_ptr 会报 invalid application of 'sizeof' to an incomplete type ；更糟的是某些编译器只给一个警告，然后生成「delete 不完整类型」的代码—— 不调用析构函数，静默泄漏 。同样的规则适用于移动构造/移动赋值。 什么时候值得用，什么时候是过度设计 场景 用 D-Pointer？ 理由 对外发布的动态库 / SDK 值得 ABI 稳定是核心诉求，客户不可能陪你重编译 插件接口 值得 插件与宿主可能用不同版本编译 大型项目里被上百个文件 include 的公共头 值得 不为 ABI，为 编译速度 ：改实现不再触发全量重编 应用内部的普通类 不值得 整个应用一起编译，没有 ABI 问题；平白多一层间接和堆分配 性能热点上的小对象 不要 额外的指针跳转会破坏缓存局部性 Qt 自己几乎所有公开类都用了 D-Pointer，这是它能在 Qt5 整个大版本内保持二进制兼容的关键。C++ ABI 的完整规则——哪些改动会破坏 ABI、内联函数的陷阱、符号可见性控制——见 C++ ABI 兼容性完全指南 与 大型 C++ 工程化与 API/ABI 治理 。"},{"a":"s6","h":"部署与打包","x":"06 部署与打包 「我这儿好好的」的终结者 # Windows：把 Qt 依赖收集到 exe 旁边 windeployqt --release --no-translations --compiler-runtime build/vision_inspector.exe # Linux：linuxdeployqt 或 CQtDeployer（Qt 官方对 Linux 支持较弱） linuxdeployqt build/vision_inspector -appimage -qmake=/opt/Qt/6.5/gcc_64/bin/qmake # macOS macdeployqt build/vision_inspector.app -dmg 现场症状 缺什么 处理 启动即报 could not find or load the Qt platform plugin \"windows\"/\"xcb\" 缺 platforms/ 目录下的平台插件 这是 最经典 的部署错误。插件必须放在 exe 旁的 platforms/ 子目录，不能只放 exe 同级 界面能开，但所有 JPG/PNG 图标不显示 缺 imageformats/ 插件 windeployqt 通常会带，手动打包时容易漏 HTTPS 全部失败，HTTP 正常 缺 OpenSSL 运行库 拷 libssl-*.dll / libcrypto-*.dll ；用 QSslSocket::supportsSsl() 在启动时自检 中文变方块 缺字体 / 缺 QT_QPA_FONTDIR （嵌入式） 嵌入式 Linux 上把字体打进 rootfs 或程序资源 数据库连不上 缺 sqldrivers/ 插件 同上，插件目录结构不能改 换台机器就崩，堆栈全是问号 混用了不同 Qt 版本或不同编译器的库 Qt 库、第三方库、你的程序 必须同一套工具链 ；MSVC 与 MinGW 的库绝不能混 交付前用 干净的虚拟机 （全新系统、没装过 Qt、没装 VC++ 运行库）跑一遍安装包，这是唯一可靠的验证方式。开发机上装了 Qt、装了各种运行库，程序会「意外地」找到它们，掩盖掉打包缺失。有条件的话把这一步做进 CI：容器里装最小系统，跑安装 + 启动 + 截图。CI 实践见 现代 CMake + 包管理 + CI 完全指南 。 许可合规不是法务的事，是选型时就要定的事。 LGPLv3 要求 动态链接 并允许最终用户替换 Qt 库——所以静态链接 Qt 做单文件 exe，除非买了商业许可，否则是违规的。另外部分模块（历史上的 Qt Charts、Qt Data Visualization 等）只提供 GPL，用了就要开源整个产品。 项目启动时就应该逐模块确认许可 ，等产品要发布了才发现用了 GPL 模块，代价极高。"},{"a":"s7","h":"高 DPI · i18n · 样式","x":"07 高 DPI · i18n · 样式 交付质量的三个细节维度 高 DPI Qt 6 默认启用 高 DPI 缩放，Qt 5 需要 QApplication::setAttribute(Qt::AA_EnableHighDpiScaling) （5.6+）。 不要写死像素 。用布局（ QLayout ）而不是绝对坐标；确实需要固定尺寸时，用 fontMetrics().height() 或 logicalDpiX() 换算。 图标要提供 @2x 版本，或者 直接用 SVG （ QIcon 支持 SVG，自动按 DPI 渲染），这是最省事的做法。 工业现场常见「一台 4K 主屏 + 一台 1080p 副屏」，窗口在两屏间拖动时 DPI 会变——测试时一定要覆盖这个场景。 国际化 // ✅ 所有面向用户的字符串都包 tr() ui->statusLabel->setText(tr( \"检测完成，共 %1 个缺陷\" ).arg(count)); // ❌ 用字符串拼接，翻译时语序无法调整 ui->statusLabel->setText(tr( \"检测完成，共 \" ) + QString::number(count) + tr( \" 个缺陷\" )); // 需要区分单复数时用 tr 的第三个参数 tr( \"%n defect(s) found\" , \"\" , count); tr() 的参数 必须是字面量 —— lupdate 是静态扫描源码提取字符串的， tr(someVariable) 提取不到。动态字符串要用 QT_TR_NOOP 标记 + 运行时 tr() 查表。另外 %1 占位符的写法允许翻译者调整语序，这正是不能用拼接的原因。 样式表的性能陷阱 QSS（Qt Style Sheet）好用但不便宜。 给一个控件设 setStyleSheet() 会导致 它和所有子控件 重新解析样式、重新计算；在 paintEvent 或高频信号里调 setStyleSheet 是性能灾难。 正确做法是「设一次样式，用属性切状态」 。 // 启动时设一次 qApp->setStyleSheet( \"QLabel[level=\\\"error\\\"] { color: red; font-weight: bold; }\" ); // 运行时只改属性 + 触发重新 polish label->setProperty( \"level\" , \"error\" ); label->style()->unpolish(label); label->style()->polish(label); 这比反复 setStyleSheet 快一个数量级，而且样式集中在一处，可维护性也更好。"},{"a":"s8","h":"陷阱总清单","x":"08 陷阱总清单 四篇 Qt 内容的速查索引 类别 陷阱 一句话对策 生命周期 有 parent 的对象又进了 shared_ptr 二选一；弱引用用 QPointer 栈对象 setParent 栈对象不进对象树 lambda 槽没传 context object 永远传第三个参数 槽里 delete this 用 deleteLater() 线程 以为 QThread 子类的槽在新线程 QThread 对象住在创建它的线程 非 UI 线程碰 QWidget / QPixmap 只传 QImage ，UI 线程再转 写死 DirectConnection 后 moveToThread 不要手写连接类型，交给 Auto 自定义类型未 qRegisterMetaType 跨线程槽会 静默不执行 ，把 Qt warning 接进日志 网络 假设 readyRead = 一条完整消息 累积缓冲 + 循环解析 QDataStream 忘了 setVersion 两端钉死同一版本号 ignoreSslErrors() 无参调用 把自签 CA 加进信任链，别关校验 性能 模型 data() 里做计算或 IO 只查表返回，计算提前做 每帧缩放全尺寸图像 缓存缩放结果，标注画在缓存之上 高频 setStyleSheet 设一次样式，用属性 + polish 切状态 构建部署 头文件没列进 target → moc 没跑 undefined reference to vtable 就查这个 缺 platforms/ 插件 用干净虚拟机验证安装包 静态链接 Qt 却只有 LGPL 项目启动时就逐模块确认许可 兼容 Qt6 的 QList 改为连续存储 持有元素引用再插入 = 悬垂，用 ASan 复检 D-Pointer 的析构函数写在头文件 必须在 .cpp 里定义，否则静默泄漏"},{"a":"s9","h":"面试题集（12 道）","x":"09 面试题集（12 道） 按难度分层，先自测再对照"},{"a":"s9-1","h":"9.1 基础（必答）","x":"9.1 基础（必答） 点击每道题展开参考答案（先自测，再对照）。 基础 QTableWidget 和 QTableView 有什么区别？几万行数据该用哪个？ QTableWidget 是「便利类」：数据直接存在视图里， 每个单元格是一个 QTableWidgetItem 对象 。几万行 × 几列就是几十万个对象，内存和构造耗时都不可接受。 QTableView 是模型/视图架构：数据在你自己的 QAbstractTableModel 里， 视图只向模型索取当前可见的那些格子 。滚动到哪取到哪，行数对性能几乎没有影响。 选择标准 几十行的固定配置表用 QTableWidget 省事； 数据量不确定或超过几百行，一律用 QTableView + 自定义模型 。 基础 QImage 和 QPixmap 该怎么选？ QImage 是 纯内存位图 ，格式明确、可以直接访问像素、 可以在任意线程使用 。 QPixmap 是 为显示优化 的图像，可能是窗口系统的资源（X11 Pixmap、GDI 对象）， 只能在主线程使用 ，但绘制到屏幕更快。 标准分工 算法处理、跨线程传递、文件读写用 QImage ； 最终显示那一步 再 QPixmap::fromImage() ，并且这一步必须在 UI 线程。 性能细节 像素格式与屏幕不一致时每次绘制都要转换。显示路径上优先用 Format_RGB32 或 Format_ARGB32_Premultiplied 。 基础 什么是 AUTOMOC？为什么会出现 undefined reference to vtable ？ CMAKE_AUTOMOC 让 CMake 自动扫描 target 的源文件，发现 Q_OBJECT 就调用 moc 生成 moc_xxx.cpp 并加入编译，省去手写生成规则。 undefined reference to vtable for X 的典型原因是 moc 没有对这个类跑 ——最常见的是 头文件没有列进 qt_add_executable / add_library 的文件列表 （AUTOMOC 只扫描 target 里列出的文件）。另一种情况是刚加上 Q_OBJECT 但构建缓存没刷新，清一次构建目录即可。 特殊规则 如果类定义写在 .cpp 里，AUTOMOC 生成的是 x.moc 而 不会自动加入构建 ，需要你在该 cpp 末尾写 #include \"x.moc\" 。 基础 程序在开发机上正常，装到客户机上启动就报 could not find the Qt platform plugin ，为什么？ 缺少 平台插件 （Windows 上是 qwindows.dll ，Linux 上是 libqxcb.so ）。Qt 的窗口系统对接是通过插件（QPA）实现的，没有它连窗口都创建不出来。 关键在于 目录结构 ：插件必须放在可执行文件旁边的 platforms/ 子目录里，只把 dll 拷到 exe 同级是不行的。用 windeployqt / linuxdeployqt 自动收集可以避免手工出错。 验证方法 用 全新的干净虚拟机 跑一遍安装包。开发机装过 Qt，程序会通过环境变量意外找到插件，掩盖打包缺失。"},{"a":"s9-2","h":"9.2 中级（区分熟练度）","x":"9.2 中级（区分熟练度） 中级 Widgets 和 QML 怎么选？给一个工业检测上位机的项目，你选哪个，为什么？ 本质差异 ：Widgets 是 CPU 光栅化 + 全程在 GUI 线程；Quick/QML 是 GPU 场景图 + 独立渲染线程。 工业检测选 Widgets ，三条理由： 功能对口 界面主体是图像显示 + 参数表格 + 结果列表，Widgets 的模型/视图体系成熟，几十万行表格没问题；QML 的 TableView 相对年轻。 可靠性 工控机显卡驱动往往老旧，还经常通过远程桌面操作。 GPU 渲染在这里是风险不是收益 ——可能降级到软件 OpenGL 反而更慢，甚至黑屏。 团队成本 团队是 C++ 背景，引入 QML 等于引入第二套语言、第二套调试链，而且 QML 是解释执行，很多错误运行时才暴露。 反过来，如果是带触摸屏的一体机、要做流畅动效、有专门的前端同学，QML 才是对的选择。 中级 自定义 QAbstractItemModel 时，为什么 data() 里不能做复杂计算？ 因为 data() 是 绝对热点 。视图每次重绘、每次滚动都会对 每个可见格子的每个 role 调用它——一屏 200 个格子 × 5 个 role（Display / Foreground / Background / ToolTip / Alignment）= 1000 次，60 帧就是每秒 6 万次。 在里面做字符串格式化（ QString::arg ）都可能成为瓶颈，做数据库查询或文件 IO 更是直接卡死。 规则 data() 里只允许 查表和返回 ，任何计算、格式化、IO 都要在数据进入模型时提前做好，存成可以直接返回的形式。 配套问题 批量插入必须用 beginInsertRows / endInsertRows 一次包住整批，逐行插入会触发 N 次视图更新； resizeColumnsToContents() 要遍历所有行，大数据量下不能用。 中级 什么是 D-Pointer（PIMPL）？为什么 Qt 到处都在用？ 把类的所有数据成员搬进一个只在 .cpp 里定义的私有实现类，公开类只保留一个指向它的指针。这样 公开类的大小和内存布局永远不变 。 Qt 用它是为了 ABI 稳定 ：往私有类里增删成员不会改变公开类的 sizeof ，动态库可以只替换 .so/.dll 而不要求调用方重新编译。这是 Qt5 能在整个大版本内保持二进制兼容的关键。 次要收益是编译速度 ：实现细节不在头文件里，改实现不会触发所有 include 者重编译。 代价 一次额外的指针跳转（破坏缓存局部性）+ 一次堆分配。 应用内部的普通类不该用 ——整个应用一起编译，没有 ABI 问题，纯粹是过度设计。 中级 Qt5 迁移到 Qt6，有哪些破坏性变化要注意？ 强制 C++17 ：GCC 7 以下、MSVC 2017 以下的工具链直接出局。 构建系统改用 CMake ：qmake 仅保留兼容，不再演进。 QList 语义变了 ——见下方，这是最容易翻车的一条。 渲染改为 RHI 抽象层 ：自定义 OpenGL 渲染代码需要适配。 部分模块移出主包 ：依赖清单和许可要重新核对。 QList 的坑 Qt5 的 QList<T> 对大对象是「指针数组」，插入删除 不会 让已有元素的指针/引用失效；Qt6 改成连续存储（等同 QVector / std::vector ）后， 任何持有元素引用再插入的老代码都变成了悬垂访问 ——而且不一定立刻崩。迁移时务必用 ASan 跑一遍完整回归。"},{"a":"s9-3","h":"9.3 高级（体现深度）","x":"9.3 高级（体现深度） 高级 用 D-Pointer 时，为什么析构函数必须定义在 .cpp 里？ 因为析构 unique_ptr<Private> / QScopedPointer<Private> 需要 Private 是 完整类型 （要知道怎么调它的析构函数、它多大）。 如果在头文件里写 ~Camera() = default; ，编译器会在 每个包含这个头文件的翻译单元 里生成析构代码——而那里 CameraPrivate 只有前向声明。 后果 std::unique_ptr 会触发 static_assert 报 invalid application of 'sizeof' to an incomplete type ，编译失败还算好的。某些实现（历史上的 QScopedPointer 、裸指针写法）只给一个警告然后生成「delete 不完整类型」的代码—— 不调用析构函数，静默泄漏 ，这才是真正危险的情况。 把 Camera::~Camera() = default; 放在 .cpp 里，此处 CameraPrivate 已完整定义，问题消失。 同样的规则适用于移动构造和移动赋值 ——它们也需要完整类型。 高级 一个显示 5000×4000 图像、带实时缺陷标注的界面很卡，你怎么优化？ 先测量再优化 ：用 QElapsedTimer 量 paintEvent 耗时，用 perf 火焰图看热点。经验上瓶颈通常在这三处： ① 每帧缩放全图 20 MPix 的双线性缩放要几十毫秒。 缓存缩放结果 ，只有源图或控件尺寸变化时才重算；预览阶段用 Qt::FastTransformation ，用户停止操作后再用高质量插值重算一次。 ② 全量重绘 标注变化时只 update(dirtyRect) 而不是 update() ； paintEvent 里用 e->region() 裁剪，跳过不在脏区里的标注。 ③ 格式转换 像素格式与屏幕不一致时每次绘制都要转换。统一成 Format_ARGB32_Premultiplied ， QPixmap::fromImage 只做一次并缓存。 再往上一层 如果图远大于视口，正确做法是 分块（tile）+ 多分辨率金字塔 ——只解码/缩放当前视口覆盖的瓦片，缩放级别切换时用预生成的低分辨率层。这也是所有地图和大图查看器的标准做法。到这个量级还可以考虑用 QOpenGLWidget 把纹理上传 GPU，让缩放平移由 GPU 完成。 高级 你负责一个要长期维护的 Qt SDK，怎么保证升级时不破坏客户的二进制兼容？ 所有公开类用 D-Pointer ，公开头文件里不出现任何数据成员，保证 sizeof 恒定。 不在头文件里内联非平凡函数 。内联代码会被编译进调用方的二进制，改了实现也不会生效，还会造成新旧行为混用。 虚函数表布局要冻结 ：不能在已有虚函数中间插入新的虚函数（会改变后面所有函数的 vtable 索引），只能追加到末尾——更稳妥的做法是 干脆不在公开类里加新虚函数 ，用非虚接口 + d 指针里的策略对象。 控制符号可见性 ： -fvisibility=hidden + 显式的 EXPORT 宏，减少导出面就是减少被依赖的面。 版本化与自检 ：提供 libVersion() ，头文件里编译期常量与运行时返回值不匹配就报错，防止头文件与库版本错配。 CI 里跑 ABI 检查工具 （ abi-compliance-checker / abidiff ），把兼容性从「靠人记住」变成「机器拦截」。 还要考虑的 Qt 类型出现在公开接口上会把 你的 ABI 和 Qt 的 ABI 绑定 ——客户必须用同一个 Qt 大版本。如果要解耦，公开接口应该只用基础类型和自己定义的 POD，把 Qt 类型藏在实现里。完整规则见 C++ ABI 兼容性指南 。 高级 Qt 的许可模式对产品架构有什么实际影响？ LGPLv3（大多数公司走的路） ：可以用于闭源商业产品，但有两条硬约束—— 必须动态链接 Qt，并且 必须允许最终用户替换 Qt 库 （提供替换说明，或提供可重新链接的目标文件）。 对架构的实际影响 ： 不能静态链接 想做「单文件 exe」的产品形态，在 LGPL 下不合规。嵌入式设备（固件是单个镜像）几乎必然要买商业许可。 逐模块确认 部分模块只提供 GPL（历史上的 Qt Charts、Qt Data Visualization、部分工具）。 用了 GPL 模块就要开源整个产品 。这必须在项目启动、技术选型时就确认，等到发布前才发现代价极高。 替代路径 需要图表功能但不想碰 GPL 模块，可以用 QCustomPlot（GPL/商业双许可，也要看）或者自己基于 QPainter 画——很多团队最后选了后者。 结论： 许可不是发布前的合规检查项，而是选型阶段的架构约束 。它直接决定了链接方式、产品形态和可用模块清单。 ⬅️ Qt 网络与本机 IPC 🧩 Qt 核心机制 🧭 全景入门 🔗 C++ ABI 兼容性 📚 目录 🏠 主页 Qt 工程化与陷阱完全指南 — CMake · Widgets vs QML · 模型视图 · D-Pointer · 部署 — Kavin Tech Notes · 2026 ↑"}]},{"u":"desktop-gui/qt_fundamentals.html","t":"Qt 核心机制完全指南","c":"桌面 GUI / Qt","s":[{"a":"","h":"","x":"Qt 核心机制完全指南 · QObject 对象树 / 信号槽与 moc / 元对象系统 / 事件循环 Kavin Tech Notes ← 主页 目录 25 min ◐ Qt 核心机制 为什么是 Qt · 选型坐标 模块地图与 Qt5 → Qt6 QObject 与对象树 信号槽：从用法到 moc 连接类型与线程语义 元对象系统与属性 事件系统与事件循环 生命周期陷阱清单 面试题集（12 道） 9.1 基础 9.2 中级 9.3 高级 Desktop GUI · Qt Core · 2026 Qt 核心机制完全指南 Qt 让人上手极快，也让人栽跟头极快——因为它在标准 C++ 之上加了三样东西： 对象树 （谁来 delete）、 元对象系统 （运行时反射与信号槽）、 事件循环 （谁在调度）。本篇把这三样从「怎么用」一路讲到「moc 生成了什么、 activate 干了什么、事件分发在哪一层落到 poll(2) 」。 核心难度 ★★★★☆ 面试出现率 极高 阅读时长 ~25 min 前置 C++ 类 / 虚函数 / 生命周期 QObject 对象树 信号槽 · moc 元对象与属性 事件循环 没写过 Qt？ 先读 Qt 零基础全景入门 （Qt 是什么 / 关键模块地图 / 第一个程序逐行拆解 / 项目分层架构），建立全景后再进本篇的深水区会顺畅很多。"},{"a":"s1","h":"为什么是 Qt · 选型坐标","x":"01 为什么是 Qt · 选型坐标 先搞清楚它到底是什么，再谈怎么用 很多人以为 Qt 是「一个 GUI 库」。更准确的说法是： Qt 是一套在 C++ 之上自建了运行时的应用框架 ，GUI 只是其中一个模块。它补上了标准库当年没有（部分至今仍没有）的东西：跨平台的线程/文件/网络抽象、序列化、插件加载、国际化，以及最核心的—— 对象间松耦合通信（信号槽） 与 运行时反射（元对象） 。 把标准 C++ 想成毛坯房：水电齐全，但没有门窗家具。Qt 是一套 精装方案 ，附带「自己的施工规范」——对象树谁负责拆、信号线怎么走、总闸在哪。好处是拎包入住，代价是 必须按它的规范施工 ：用标准 C++ 的习惯去动 Qt 的结构，往往就是崩溃的来源。 桌面 GUI 技术选型 方案 语言 体积 / 启动 跨平台 适用场景 主要代价 Qt Widgets C++ 中（~20–40 MB）/ 快 Win / Linux / macOS / 嵌入式 工业软件、仪器上位机、CAD 学习曲线、许可合规 Qt Quick / QML QML + C++ 中 / 中（需 JS 引擎） 同上 + 车机 / 移动 动效丰富的 HMI、触摸屏 GPU 依赖、QML 与 C++ 边界易失控 Electron JS/TS 大（>100 MB）/ 慢 三大桌面 偏内容展示、迭代快的工具 内存占用、吃不到 C++ 生态 WPF / WinUI C# 小 / 快 仅 Windows 纯 Windows 业务系统 锁定平台 Dear ImGui C++ 极小 / 极快 依赖渲染后端 调试面板、算法可视化 即时模式，不适合复杂表单 MFC C++ 小 / 快 仅 Windows 历史存量维护 不用于新项目 工业检测、机器视觉几乎是 Qt 的主场： 算法侧本来就是 C++ （OpenCV / Halcon / 相机 SDK 全是 C++ 接口），换语言就要多封装一层；设备端跑 Linux、开发机是 Windows；高频刷新的图像显示又对 GC 语言不友好。Qt 把这三点一次解决。 Qt 的许可，一句话讲清 LGPLv3 ：可用于闭源商业产品，但必须 动态链接 并允许最终用户替换 Qt 库。绝大多数公司走这条路。 GPLv3 ：部分模块与工具只给 GPL，用了就要开源。 选型时必须逐模块确认 ，这是真实项目里最容易踩的合规坑。 商业许可 ：可静态链接、不受传染，按席位收费。单文件固件的嵌入式设备通常被迫走这条。"},{"a":"s2","h":"模块地图与 Qt5 → Qt6","x":"02 模块地图与 Qt5 → Qt6 先建立地形图，再深入 应用层：你的业务代码 窗口 / 业务逻辑 / 算法调用 / 设备驱动封装 Qt Widgets 传统控件、布局 桌面原生外观 Qt Quick / QML 声明式 UI、动效 场景图 + GPU Qt Network TCP/UDP/SSL HTTP (QNAM) 其他模块 Sql / Concurrent SerialPort / Test Qt Core — 所有模块的地基 QObject 对象树 元对象系统 (moc) 信号槽 事件循环 容器 / 字符串 / 文件 / 线程 / 定时器 / 插件 / 国际化 Widgets 与 QML 之争只是上层皮肤，脚下都是同一套 Qt Core——本篇余下内容全在讲底座这四样 Qt5 → Qt6 的关键变化 方面 Qt 5 Qt 6 迁移影响 C++ 标准 C++11（5.15 起可选 17） 强制 C++17 GCC 7 / MSVC 2017 以下直接出局 构建系统 qmake 为主 CMake 为主 ，qmake 仅兼容 构建脚本要重写，见 工程化篇 渲染后端 直接调 OpenGL RHI 抽象层（Vulkan/Metal/D3D/GL） 自定义 OpenGL 渲染要适配 容器 QList 与 QVector 是两个东西 QList 就是 QVector （连续存储） 依赖「插入不失效引用」的老代码会出问题 字符串 QString 内部 UTF-16 同上，新增 QStringView 等只读视图 可渐进采用，注意 view 的悬垂 异步 QFuture 功能有限 QFuture::then() 、 QPromise 并发写法可简化，见 并发篇 模块拆分 大包 部分模块移到 Qt Additional Libraries 依赖清单与合规都要重核 Qt6 最容易被忽略的破坏性变化是 QList 。 Qt5 对大对象用「指针数组」，插入删除不会让已有元素的引用失效；Qt6 改成连续存储后语义等同 std::vector —— 持有元素引用再插入的老代码全部变成悬垂访问，而且不一定立刻崩 。迁移时用 ASan 跑一遍回归。"},{"a":"s3","h":"QObject 与对象树","x":"03 QObject 与对象树 Qt 的第一套内存管理规范 对象树（Object Tree） ：每个 QObject 可以有一个 parent 和任意多个 children ，构造时自动登记进 parent 的孩子列表。 parent 析构时会依次 delete 所有 children ；child 先死则自动从列表里摘掉。这就是 Qt 在智能指针普及之前给出的所有权答案。 对象树像 公司的组织架构 ：部门撤销时下属岗位一并撤销，不用 HR 一个个通知；员工提前离职也会自动从花名册除名。麻烦在于—— 一个人同时在编制内又被你私下签了合同，就会被「裁员」两次。 QMainWindow root · 栈上或 new QToolBar parent = window QWidget (central) parent = window QTimer 非可视也进树 QPushButton parent = central QLabel label; 栈对象 + setParent ← double free 栈先析构，parent 再 delete 一次 析构顺序：root 析构 → 遍历 children 逐个 delete → 递归向下 对象树的所有权链：非可视对象（QTimer）同样受管；栈对象挂进树就埋下 double free 谁 delete 谁：最短示例 void setup(QWidget* parent) { auto * label = new QLabel( \"状态\" , parent); // ✅ 不写 delete：parent 析构时会 delete 它 } // ❌ 经典坑：栈对象被设了 parent，析构顺序反过来 QLabel label( \"y\" ); // 先声明 → 后析构 QWidget w; // 后声明 → 先析构 label.setParent(&w); // w 析构 → 对一个栈地址执行 delete → UB // 反过来写（w 在前、label 在后）恰好能跑，但这是靠声明顺序活着 // QObject 不可拷贝：拷贝构造与赋值都是 = delete 的， // 因为身份（对象名、连接、父子关系）本身复制不了。 // 想要值语义就用普通 struct，别继承 QObject。 三条所有权路径：怎么共存 ① parent 托管 new QLabel(txt, parent) 谁 delete：parent 默认选择 · 控件 / 定时器 / socket child 先死也会自动摘除 ② 智能指针 unique_ptr / QPointer 谁 delete：作用域 / 无人 顶层窗口 · 无自然 parent 的对象 QPointer 是弱引用，只观察 ③ 栈对象 QWidget w; 谁 delete：作用域 main() 里的顶层窗口、局部对话框 绝不 setParent 两条路径同时认领同一个对象 = double free ①+② shared_ptr 持有已有 parent 的对象 ｜ ①+③ 栈对象 setParent 症状：关窗口时随机崩溃，堆栈落在完全无关的地方 每个 QObject 只能走一条路径。混用两条不会立刻报错，而是在析构时炸给你看 工具 语义 什么时候用 parent-child 父独占子，父死子死 默认选择 ：窗口下的控件、归属某个管理对象的定时器/socket std::unique_ptr 作用域独占 顶层窗口、无自然 parent 的对象、工厂返回值 QPointer<T> 弱引用 ，对象析构后自动变 nullptr 缓存「可能已被别人删掉」的指针；跨模块持有 QScopedPointer Qt 版 unique_ptr（无移动） PIMPL 的 d_ptr ，见 工程化 · D-Pointer std::shared_ptr<QObject> 共享所有权 基本别用 ：parent 会在引用计数还没归零时先 delete 掉对象 不要把有 parent 的 QObject 塞进 shared_ptr 。 这类 double free 只有 ASan 看得清，参见 Crash 定位实战 ；智能指针本身的语义边界见 C++ 智能指针深度解析 。"},{"a":"s4","h":"信号槽：从用法到 moc","x":"04 信号槽：从用法到 moc C++ 里没有的东西，Qt 是怎么造出来的 信号槽（Signal & Slot） ： 发布-订阅 式的对象间通信。发送方 emit 信号，完全不知道谁在接收；接收方把自己的成员函数连上去。连接 运行时建立 、可动态增删，而签名在 编译期 检查（新语法下）。 信号槽像 小区广播 ：广播站喊「快递到了」，不关心几户人在听，住户自己决定订不订、随时可退订。传统回调则是 互相留手机号 ——发送方必须持有接收方的指针，两边耦合死。 四种连接写法，一次看完 class Camera : public QObject { Q_OBJECT // ← 必须：告诉 moc 处理这个类 signals : // signals 展开为 public（Qt6 起） void frameReady( const QImage& img); // 只声明，实现由 moc 生成 }; // ① ❌ Qt4 老语法：签名是字符串，拼错只在运行时给一行 warning connect(camera, SIGNAL(frameReady(QImage)), viewer, SLOT(render(QImage))); // ② ✅ 函数指针：编译期检查签名，槽不必声明在 slots: 下 connect(camera, &Camera::frameReady, viewer, &Viewer::render); // ③ ⚠️ 裸 lambda：只跟 sender 绑生命周期 connect(camera, &Camera::frameReady, [viewer]( const QImage& im) { viewer->render(im); // viewer 先死 → 每次 emit 都是 UAF }); // ④ ✅ lambda + context object（第三个参数）——默认就该这么写 connect(camera, &Camera::frameReady, viewer, [viewer]( const QImage& im) { viewer->render(im); }); // context 同时决定两件事：viewer 析构 → 连接自动断开； // lambda 在 viewer 所属线程执行。 // 重载信号在 ②③④ 下要消歧：qOverload<int>(&Cls::sig) 对比项 SIGNAL/SLOT 宏（老） 函数指针（新，Qt5+） 错误发现时机 运行时，仅打印一行 warning 编译期 报错 参数类型 字符串逐字匹配（ Camera::Mode 与 Mode 不是同一个） 支持隐式转换（ int → double ） 可连接的目标 只能是 slots: 下的成员函数 任意成员函数、普通函数、静态函数、lambda 重载信号 天然支持（字符串自带签名） 要写 qOverload<int>(&Cls::sig) 消歧 唯一还需要老语法的场景是 QML/脚本侧按名字动态连接。新代码一律用函数指针语法。 moc 到底做了什么 C++ 没有反射，而信号槽需要「运行时按索引找到某个成员函数并调用」。Qt 的解法不是宏黑魔法，而是 加一个代码生成步骤 ： moc 扫描带 Q_OBJECT 的头文件，生成一个 moc_xxx.cpp 参与编译。构建侧怎么接线见 工程化 · CMake + AUTOMOC 。 camera.h 含 Q_OBJECT moc 代码生成器 moc_camera.cpp 元信息 + 信号实现 编译 + 链接 与 camera.cpp 一起 moc_camera.cpp 里生成的三样东西 ① staticMetaObject：类名 / 信号槽名 / 参数类型的静态字符串表 ② 信号函数体：frameReady() 的实现（你从来没写过它） void* _a[] = { nullptr, &_t1 }; QMetaObject::activate(this, &smo, 0, _a); ③ qt_static_metacall：按索引分派到真实成员函数的 switch moc 不修改你的代码，只是额外生成一个翻译单元把「反射表」补上。所以 emit 一个信号 = 把参数打包成 void* 数组交给 activate emit frameReady(img) 你写的一行代码 Camera::frameReady() moc 生成的函数体 QMetaObject::activate 加读锁，遍历连接列表 对每条连接判断 连接类型 = Auto ? 比较收发双方线程 同线程 → Direct qt_static_metacall 立即调用 同步返回，栈上继续 跨线程 → Queued 参数深拷贝（需已注册元类型） 封成 QMetaCallEvent postEvent 到接收者线程队列 判定发生在 emit 的那一刻， 不是 connect 的时刻 —— 这点 决定了 moveToThread 之后 同一条连接会自动改变行为。 emit → activate → 按连接类型分流。Queued 分支要求参数类型可拷贝且已注册 性能：信号槽到底慢不慢 「比直接调用慢 10 倍」这个数量级大致对，但它不是判断依据。 正确的判据是「这条路径的调用频率 × 单次开销，占不占预算」 ： Direct = 读锁 + 遍历连接列表 + 一次间接分派，现代 CPU 上 几十纳秒 。UI 交互、状态通知这类每秒几千次以内的路径完全不用考虑。 Queued 额外付参数深拷贝 + 一次堆分配 + 队列锁，比 Direct 贵一个量级。 真成了热点就 批量化 ：攒够 N 帧或到时间片再发，热路径内部用裸回调，只在模块边界发信号。跨线程传大图像要用 QImage / QByteArray 这类 隐式共享（COW） 类型，拷贝只是加引用计数。"},{"a":"s5","h":"连接类型与线程语义","x":"05 连接类型与线程语义 五个枚举值，决定了槽在哪个线程、什么时候跑 发送方线程（emit 所在） 接收方线程（receiver->thread()） Direct 槽立即执行 · 同步返回 跨线程用它 = 在错误线程跑槽 · data race Queued 入事件队列 → 事件循环取出后执行（异步） 拷贝参数打包成 QMetaCallEvent BlockingQueued 槽在此执行，执行完才唤醒发送方 发送方阻塞 · 同线程用它必死锁 Auto（默认） 在 emit 的那一刻比较两边线程：同线程 → 走 Direct，跨线程 → 走 Queued Unique（标志） 不影响线程，只保证同一组 sender / signal / receiver / slot 不被重复连接 连接类型唯一决定的事：槽在哪条线程的栈上跑，以及发送方要不要等它 默认的 AutoConnection 覆盖绝大多数场景，另外四个各解决一件具体的事：强制同步、强制异步、拿跨线程返回值、防重复连接。 判定发生在 emit 的那一刻，不是 connect 的时刻。 所以 moveToThread() 之后，已有的 Auto 连接会自动从 Direct 变成 Queued；而你手动写死的 DirectConnection 不会 变，就成了跨线程直接调用——Qt 多线程里最隐蔽的一类竞态。详见 Qt 并发与跨线程 · 线程亲和性 。 Queued 连接为什么要注册元类型 emit done(r) r 是自定义 struct activate 要存参数 查元类型表：这个类型 怎么构造 / 拷贝 / 析构？ ✅ 查到了 深拷贝一份进 QMetaCallEvent postEvent → 接收线程正常执行槽 ❌ 没查到 Cannot queue arguments of type 'InspectResult' 一行 warning，然后静默丢弃这次调用 让它查得到：两步 Q_DECLARE_METATYPE(InspectResult) // 头文件，命名空间外 qRegisterMetaType<InspectResult>(); // main 里一次 类型必须可默认构造、可拷贝构造、可析构 「不报错也不工作」是 Queued 连接最难查的失败形态。所以启动时务必用 qInstallMessageHandler 把 Qt 的 warning 接进项目日志——答案往往就在那几行没人看的输出里 跨线程直接改 UI：最常见的一类崩溃 ❌ 在工作线程里碰 QWidget void Worker::run() { for ( auto & f : frames) { process(f); m_label->setText(tr( \"已处理 %1\" ).arg(f.id)); // ↑ QWidget 只能在 GUI 线程碰 // 症状：偶发花屏 / 断言 / 崩在 QPainter 里 } } ✅ 发信号回主线程 void Worker::run() { for ( auto & f : frames) { process(f); emit progress(f.id); // 跨线程 → Auto 走 Queued } } // 主线程侧：label 的更新回到 GUI 线程的事件循环里做 connect(worker, &Worker::progress, label, [label]( int id) { label->setText(QStringLiteral( \"已处理 %1\" ).arg(id)); }); 「点一次按钮，槽跑了三遍」几乎总是重复 connect。 典型场景是在 showEvent 、 setModel 这种会被调多次的函数里连接。要么只在唯一入口连，要么统一加 Qt::UniqueConnection ；需要精确断开就存下 connect 的返回值 QMetaObject::Connection 。"},{"a":"s6","h":"元对象系统与属性","x":"06 元对象系统与属性 C++ 的运行时反射，Qt 自己补上了 元对象系统（Meta-Object System） ：由 Q_OBJECT 宏 + moc 生成的 QMetaObject 构成的运行时类型信息体系。它让程序能在运行时问出「这个对象是什么类、有哪些属性和方法、把叫 start 的那个调一下」——信号槽、QML 绑定、Designer、序列化都建在它上面。 声明一个属性只要一行宏，剩下的全由 moc 填进元信息表——于是这个成员变量同时具备了「按名字读写」「QML 可绑定」「样式表可选择」三种能力： class Inspector : public QObject { Q_OBJECT Q_PROPERTY( double threshold READ threshold WRITE setThreshold NOTIFY thresholdChanged) Q_PROPERTY(QString deviceId READ deviceId CONSTANT) // 无 NOTIFY = 绑定不了 public : double threshold() const { return m_threshold; } void setThreshold( double v) { if (qFuzzyCompare(v, m_threshold)) return ; // 必写：防止信号风暴 m_threshold = v; emit thresholdChanged(v); } Q_INVOKABLE void reset(); // 可被 QML / invokeMethod 按名字调用 signals : void thresholdChanged( double ); private : double m_threshold = 0.85 ; }; // moc 把上面这些登记进 staticMetaObject，于是运行时可以： ins.setProperty( \"threshold\" , 0.9 ); // 按名字写 ins.property( \"threshold\" ).toDouble(); // 按名字读 QMetaObject::invokeMethod(&ins, \"reset\" , Qt::QueuedConnection); 三种写入入口 setThreshold(v) setProperty(\"…\") QML 赋值 WRITE 函数（你写的） ① 与旧值比较，相同就 return ② 写成员变量 ③ emit NOTIFY 信号 QML 数据绑定 text: inspector.threshold 自动刷新 样式表状态选择器 QPushButton[status=\"error\"] + style()->polish() 序列化 / 自动化测试 遍历 propertyCount() 一次 dump 成 JSON 漏掉第 ① 步的后果：信号风暴 A 的槽写 B、B 的槽又写回 A → 每次赋值都 emit → 无限递归 症状是栈溢出，不是死循环卡住——很多人第一次见会以为是 QML 引擎的 bug NOTIFY 是整个属性系统的枢纽：没有它，QML 里读到的就是「读一次就不动」的死值 QObject::staticMetaObject superdata = nullptr className = \"QObject\" signals: destroyed(), objectNameChanged() Camera::staticMetaObject superdata = &QObject::… className = \"Camera\" signals: frameReady(QImage) errorOccurred(int,QString) 静态方法表 qt_static_metacall 运行时能力 qobject_cast<T*> property / setProperty invokeMethod connect 按索引分派 QML 绑定 / Designer super staticMetaObject 通过 superdata 串成链表——这就是 qobject_cast 不依赖 RTTI 也能工作的原因 每个 Q_OBJECT 类有一份静态元对象，靠 superdata 指针串成继承链 qobject_cast 为什么不用 dynamic_cast ：它沿 superdata 链比较类名， 不依赖 RTTI ，因此在 -fno-rtti 编译、跨动态库边界时依然可靠，而且更快。各种 cast 的对比见 C++ 类型转换深度指南 。 忘了 Q_OBJECT 的症状很有辨识度 ：编译通过，但 className() 返回 基类名 、信号槽不工作——没有这个宏就不生成 moc 文件。变体是加了宏却没重跑 moc，报 undefined reference to vtable ，清一次构建目录即可。"},{"a":"s7","h":"事件系统与事件循环","x":"07 事件系统与事件循环 Qt 程序的心脏 事件循环（Event Loop） ：一个「取事件 → 分发 → 执行」的无限循环。 exec() 启动它之后，鼠标点击、定时器到期、socket 可读、跨线程槽调用全都变成事件排队进来。 每个线程最多一个事件循环 ，没有它的线程收不到 Queued 信号、也跑不了 QTimer。 事件循环像 前台接待 ：访客（鼠标、键盘、网络数据、定时提醒）都到前台排队，接待员按顺序叫号，领到对应的办公室（目标 QObject）。 某间办公室谈了 10 分钟，后面所有人都在大厅干等 ——这就是界面卡死的本质。 从 exec() 到 poll() QCoreApplication::exec() QEventLoop::exec() while (!quit) processEvents(); QAbstractEventDispatcher::processEvents() 平台实现：Linux 走 QEventDispatcherGlib（GMainContext） 或 QEventDispatcherUNIX；Windows 走消息泵 OS 阻塞等待 poll(2) / GetMessage() fd 可读 · 超时 · 唤醒管道 Qt 事件队列 postEvent 投进来的 含跨线程 QMetaCallEvent 分发到目标对象 notify → eventFilter → event() → mousePressEvent() 等 事件循环的四层：exec → EventLoop → EventDispatcher → 操作系统阻塞原语 「Qt 在 Linux 上用 epoll」是 误传 ： QEventDispatcherUNIX 与桌面默认的 QEventDispatcherGlib 底层都是 poll(2) ，也就是 O(n) 于 fd 数量 。上万连接的服务端本来也该用 Asio/epoll，见 C++ 异步网络框架指南 。 一个事件被送到目标手上，要过几道关 事件产生：OS 消息 · postEvent 入队 · sendEvent 直达 QApplication::notify(receiver, ev) 全局唯一入口，重写它能截住一切 装在 qApp 上的事件过滤器 全局快捷键 · 输入法 · 埋点 return true → 事件被吃掉，下面全都不执行 装在 receiver 上的事件过滤器 不改子类就改行为 return true → 同上 receiver->event(ev) 重写它可统一处理，别忘了调基类实现 mousePressEvent() / keyPressEvent() / paintEvent() event() 按 ev->type() 分派到这里 调 ignore() → 事件向父控件冒泡 过滤器排在处理函数 之前 ，这就是它能改掉别人家控件行为的原因 事件过滤器是 Qt 里性价比最高的一招： 不继承、不改源码，就能改掉任意控件的行为 。最短实现只有一个虚函数： // 让某个 QLineEdit 吃掉回车键，改成\"回车即提交\" bool Form::eventFilter(QObject* obj, QEvent* ev) { if (obj == m_edit && ev->type() == QEvent::KeyPress) { auto * k = static_cast <QKeyEvent*>(ev); if (k->key() == Qt::Key_Return) { submit(); return true ; // 吃掉：QLineEdit 收不到这个键 } } return QWidget::eventFilter(obj, ev); // 其余交还给基类 } // 安装：m_edit->installEventFilter(this); // 装到 qApp 上就是全局过滤器，能看到程序里每一个事件。 事件 vs 信号：两套机制，别搞混 事件 QEvent 方向： 发给 某个确定的对象 来源：多数由系统 / 框架产生 鼠标 · 键盘 · 重绘 · 定时器 可拦截：过滤器 return true 即终止 可冒泡：ignore() 后交给父控件 信号 Signal 方向：对象 发出 ，不知道谁在收 来源：多数由业务代码 emit 状态变化 · 数据就绪 · 出错 不可拦截：连上就一定会调 不冒泡：一次分发给全部槽 交汇点：Queued 连接就是用事件实现的 跨线程 emit → 「槽 + 参数副本」打包成 QMetaCallEvent → postEvent 到接收者线程队列 推论：接收者线程 没有事件循环 时，Queued 信号永远不会被执行——因为没人来取那个事件 动手感受：sendEvent 与 postEvent 的区别 点按钮模拟不同的投递方式，看执行顺序。 sendEvent 立即同步调用， postEvent 排队等事件循环下一轮。 sendEvent（同步） postEvent（排队） 混合：post 两个 + send 一个 清空 耗时槽 = 界面冻结 槽函数是被事件循环 同步调用 的。槽没返回，循环就取不到下一个事件，重绘请求排在队里没人处理——界面于是冻住。Windows 上超过 5 秒还会被系统标成「无响应」并给窗口蒙灰。 别用 processEvents() 硬撑刷新，它是 Qt 里最危险的便利函数。 它在你的调用栈中间重新进入事件分发，等于把一段本该原子的逻辑劈成两半、中间插入任意用户操作——重入、 this 被删、容器被改，三样都可能。正确做法始终是把耗时活儿挪出 UI 线程，见 Qt 并发与跨线程 · moveToThread 。"},{"a":"s8","h":"生命周期陷阱清单","x":"08 生命周期陷阱清单 线上崩溃的常客，按出现频率排序 ① double delete 两条所有权同时认领一个对象 parent 先 delete shared_ptr 归零 / 栈退出 再 delete 症状：关窗口时随机崩 堆栈落在完全无关的地方 ② 悬垂 sender / 捕获 lambda 槽没传 context object 被捕获的对象先析构 连接只跟 sender 绑，仍然有效 症状：每次 emit 都是 UAF 定时器驱动时表现为周期性崩溃 ③ 跨线程改 UI 工作线程直接调 widget 方法 QWidget 全体非线程安全 绘制状态被两条线程同时写 症状：偶发花屏 / 断言 崩在 QPainter 里，看不出关联 三者的共同点：崩溃点与犯错点隔了很远 所以定位手段不是读堆栈，而是 ASan + dumpObjectInfo() 把「谁持有谁、谁连了谁」摊开看 下面这张表按出现频率把十种陷阱列全，但它们最终都收敛到上面三种形态 # 陷阱 症状 正确做法 1 有 parent 的对象又被手动 delete / 放进 shared_ptr 关窗口时随机崩溃，堆栈无关 所有权二选一； QPointer 做弱引用 2 栈对象 setParent 出作用域后 parent 再 delete 一次 栈对象不进对象树 3 lambda 槽没传 context object 对象死后 emit → UAF 永远传第三个参数 4 在槽里 delete this 或 delete sender 返回 activate 继续遍历 → 崩 用 deleteLater() 5 重复 connect 槽执行 N 次，数据被处理多遍 Qt::UniqueConnection 6 自定义类型未 qRegisterMetaType 跨线程槽 静默不执行 注册 + 把 Qt warning 接进日志 7 在非 UI 线程碰 QWidget 偶发花屏 / 断言 用信号回主线程再动 UI 8 QObject 在 A 线程 new、在 B 线程用 定时器不触发、Queued 走错线程 moveToThread 明确归属 9 循环 connect（A→B→A） 信号无限递归，栈溢出 setter 里先比较再 emit 10 忘写 Q_OBJECT 或 moc 未重跑 信号不工作 / vtable 未定义 加宏 + 清构建目录 为什么槽里只能 deleteLater ❌ 槽里 delete this activate() 正在 遍历连接列表 槽执行 delete this; 返回 activate() 对象已经没了 继续遍历 → 崩 ✅ 槽里 deleteLater() 槽执行 投一个 DeferredDelete 槽正常返回 activate 遍历完 栈退回事件循环 取出队列里的事件 此刻才真正析构 代价：deleteLater 依赖事件循环。所在线程不跑 exec()，这个事件永远没人取——对象直接泄漏 deleteLater 不是「稍后删」，而是「投一个事件，等控制权回到事件循环时才删」 只做计算的 std::thread 、或者 run() 里没调 exec() 的 QThread 子类，都属于「没有事件循环」——在那种线程上 deleteLater() 等于泄漏。这类泄漏 Valgrind 能直接看到，排查手法见 C++ 内存泄漏体系化指南 。 调试对象树的两个实用手段： dumpObjectTree() 打印以某对象为根的整棵树， dumpObjectInfo() 打印该对象的所有信号槽连接。定位「这个信号到底连了几个槽」比下断点快得多。前提是给关键对象都 setObjectName() ，否则输出全是 QWidget 认不出来。"},{"a":"s9","h":"面试题集（12 道）","x":"09 面试题集（12 道） 按难度分层，先自测再对照"},{"a":"s9-1","h":"9.1 基础（必答）","x":"9.1 基础（必答） 点击每道题展开参考答案（先自测，再对照）。 基础 信号槽和普通回调函数相比，优势和代价分别是什么？ 优势 ：发送方与接收方完全解耦——发送方不需要持有接收方的指针，也不需要知道对方的类型；一个信号可以连多个槽，一个槽也可以接多个信号；连接可以在运行时动态增删；接收方析构时连接自动断开，不会留下野回调。 代价 ：需要继承 QObject、写 Q_OBJECT 、引入 moc 这个额外的构建步骤；单次调用比直接函数调用慢一个量级（几十纳秒）；跨线程连接还有参数拷贝和堆分配开销。 选型判断 高频热路径（每帧每像素）用回调或直接调用；模块边界、状态通知、UI 交互用信号槽。 基础 QObject 的父子关系（对象树）解决了什么问题？有 parent 的对象需要手动 delete 吗？ 解决的是 GUI 场景下大量小对象的所有权问题 ：一个窗口下有几十上百个控件，逐个管理生命周期既啰嗦又易错。对象树让 parent 在析构时自动 delete 全部 children，递归向下。 不需要手动 delete ，而且不应该——手动 delete 之后 child 会自动从 parent 的列表中摘除，所以单次手动 delete 不会 double free；但一旦和 shared_ptr 或栈对象混用，就会出现两套所有权同时释放的问题。 基础 Q_OBJECT 宏做了什么？漏写会发生什么？ 它声明了元对象相关的成员： staticMetaObject 、虚函数 metaObject() 、 qt_metacast() 、 qt_metacall() ，并且是给 moc 的标记 ——moc 扫到它才会为这个类生成 moc_xxx.cpp （里面有元信息表、信号函数体、静态分派函数）。 漏写的症状 ：编译能过，但该类没有自己的元对象， metaObject()->className() 返回基类名；自定义信号没有实现体，链接期报 undefined reference ；用老语法 connect 时运行期报「no such signal」。 变体 加了宏但构建系统没重跑 moc，会报 undefined reference to vtable for X 。清一次构建目录即可，不是代码问题。 基础 为什么在槽函数里做耗时计算会让界面卡死？ 因为 GUI 事件（重绘、鼠标、键盘）都排在 主线程的事件循环 里，靠循环逐个取出分发。槽函数是被这个循环同步调用的——槽没返回，循环就取不到下一个事件，重绘请求得不到处理，界面就是冻住的。 正确做法是把耗时工作交给工作线程（ QThread + moveToThread 、或 QtConcurrent::run ），通过信号把进度和结果回传主线程。 不要用 processEvents() 硬撑 ，它会引发重入和 UAF。"},{"a":"s9-2","h":"9.2 中级（区分熟练度）","x":"9.2 中级（区分熟练度） 中级 五种连接类型分别是什么语义？ AutoConnection 的判定发生在什么时候？ DirectConnection ：在 发送方线程 同步调用，等价于普通函数调用。 QueuedConnection ：打包成事件投递到 接收方线程 的队列，异步执行。 BlockingQueuedConnection ：同上，但发送方阻塞等到槽执行完。 同线程使用必然死锁。 AutoConnection （默认）：同线程走 Direct，跨线程走 Queued。 UniqueConnection ：是个标志位，与上面按位或使用，保证同一组 sender/signal/receiver/slot 只连一次。 关键细节 Auto 的判定在 emit 时刻 ，用 QThread::currentThread() 与 receiver->thread() 比较，不是 connect 时刻。所以 moveToThread() 之后已有连接会自动改变行为，无需重连；反过来，写死 DirectConnection 的连接不会变，moveToThread 之后就变成了跨线程直接调用，是隐蔽的竞态源。 中级 跨线程用信号槽传自定义结构体，为什么槽不执行？ 因为 Queued 连接需要把参数 拷贝一份存进事件 ，Qt 必须通过元类型系统知道这个类型怎么构造、拷贝、析构。自定义类型没注册时，Qt 只在控制台打一行 QObject::connect: Cannot queue arguments of type 'X' ，然后 静默丢弃这次调用 ——不崩溃、不抛异常，所以特别难查。 解决：头文件里 Q_DECLARE_METATYPE(X) （放在命名空间外），程序启动时 qRegisterMetaType<X>() 。类型必须 可默认构造、可拷贝构造、可析构 。 工程建议 用 qInstallMessageHandler 把 Qt 的 warning 接进项目日志系统。很多「莫名其妙不工作」的 Qt 问题，答案就在那几行被忽略的 warning 里。 中级 connect 用 lambda 时，第三个参数（context object）有什么用？不传会怎样？ context object 有两个作用： ① 生命周期绑定 ——context 析构时该连接自动断开； ② 线程归属 ——lambda 在 context 所属的线程执行（配合 Auto 连接类型）。 不传的话，连接只跟 sender 绑定。如果 lambda 捕获了别的对象而那个对象先析构，之后每次 emit 都是访问已释放内存；如果是跨线程 emit，lambda 还会在 发送方线程 执行，可能在工作线程里碰了 UI。 写法 connect(sender, &S::sig, receiver, [receiver]{ ... }); —— 只要 lambda 里用到了某个 QObject，就把它作为 context 传进去。 中级 事件（QEvent）和信号（Signal）有什么本质区别？Queued 连接和事件是什么关系？ 方向不同 ：事件是「发给某个特定对象」的，有明确接收者，由事件循环分发；信号是「对象发出的通知」，发送方不知道谁在接收。 可拦截性不同 ：事件可以被 eventFilter 拦下、可以 ignore() 后向父控件冒泡、可以重写 event() 统一处理；信号一旦连上就一定会调，无法拦截。 关系 ：Queued connection 正是 用事件实现 的——跨线程 emit 时 Qt 把「槽 + 参数副本」打包成 QMetaCallEvent ，postEvent 到接收者线程队列。所以「接收者线程没有事件循环」时，Queued 信号永远不会被执行。"},{"a":"s9-3","h":"9.3 高级（体现深度）","x":"9.3 高级（体现深度） 高级 从 emit 到槽被调用，中间经过了哪些环节？moc 在其中扮演什么角色？ emit 只是个空宏，展开后就是普通函数调用 frameReady(img) 。 这个函数的 实现体是 moc 生成的 （你只写了声明）。它把参数地址装进一个 void* _a[] 数组，调用 QMetaObject::activate(this, &staticMetaObject, signalIndex, _a) 。 activate 加读锁，取出该对象在这个信号索引上的连接列表。 对每条连接判断连接类型（Auto 时比较线程）：Direct 就通过 qt_static_metacall 按槽索引 switch 到真实成员函数并传参；Queued 就深拷贝参数、构造 QMetaCallEvent 、 postEvent 到接收者线程。 Queued 的那条路径，最终由接收者线程的事件循环取出事件，再执行同样的 qt_static_metacall 分派。 moc 的角色 C++ 没有反射，而信号槽需要「运行时按索引找到并调用一个成员函数」。moc 通过生成一张 静态元信息表 + 一个 switch 分派函数 把反射能力补上——本质是用 代码生成 换取运行时能力，而不是用宏或模板黑魔法。 高级 qobject_cast 与 dynamic_cast 有什么区别？为什么 Qt 要自己造一个？ dynamic_cast 依赖编译器生成的 RTTI （typeinfo），沿虚表指针找类型信息。 qobject_cast 走的是 Qt 自己的元对象链：从对象的 metaObject() 出发，沿 superdata 指针逐级比较类名字符串。 dynamic_cast qobject_cast 依赖 RTTI 是 否， -fno-rtti 也能用 跨动态库 可能失败（不同 so 的 typeinfo 未必合并） 可靠 适用类型 任意多态类型 仅 QObject 派生且带 Q_OBJECT 速度 较慢 更快（简单的链表遍历） 动机 Qt 要支持插件化（跨 so 边界传对象）、要支持关掉 RTTI 的嵌入式构建，还要在热路径上频繁做类型判断（事件分发、样式系统）。这三点 dynamic_cast 都不理想，所以顺手用已有的元对象链自己实现了一个。 高级 processEvents() 为什么危险？如果必须用，怎么用才相对安全？ 它在你的调用栈中间 重新进入事件分发 ，等于把一段本该原子的逻辑劈成两半，中间插入了任意的用户操作。三类后果： 重入 用户再点一次按钮，同一个槽被递归触发，状态机被打乱。 this 被删 用户在这期间关闭窗口， processEvents 返回后你继续访问成员变量，就是 use-after-free。 状态不一致 你正在遍历的容器被另一个槽修改，迭代器失效。 相对安全的用法 ：传 QEventLoop::ExcludeUserInputEvents 挡掉鼠标键盘；进入前用 QPointer<QObject> guard(this) ，返回后先判 if (!guard) return; ；把可能重入的按钮先 setEnabled(false) 。 但这些都是补丁。 根治方案是把耗时逻辑挪出 UI 线程 ，或者把长任务切成小块用 QTimer::singleShot(0, ...) 分片调度——后者天然回到事件循环，不会重入当前栈帧。 高级 Qt 的事件循环在 Linux 上底层用的是什么？它适合做高并发网络服务端吗？ Qt 自带的 QEventDispatcherUNIX 用 poll(2) ；桌面 Linux 上默认启用的是 QEventDispatcherGlib ，走 GLib 的 GMainContext ，底层同样是 poll 。 不是 epoll ——这是一个常见的误答。 因此 Qt 的 IO 多路复用是 O(n) 于 fd 数量 ：每轮都要把整个 fd 数组交给内核、返回后再线性扫描。几十上百个连接完全没问题（这正是客户端场景），但要管理上万连接就会在 poll 上耗掉大量 CPU。 结论与替代 Qt 的事件循环是为 桌面/嵌入式客户端 设计的：fd 少、事件类型杂（GUI + 定时器 + IO 混在一起）、需要与窗口系统集成。高并发服务端应该用 epoll/io_uring 或 Asio，见 异步网络框架指南 。如果一个 Qt 应用确实要扛大量连接，常见架构是 把网络层放到独立线程用 Asio/裸 epoll 跑，只通过 Queued 信号把结果送回 UI 线程 。 ⬅️ Qt 零基础全景入门 ➡️ Qt 并发与跨线程 🔌 Qt 网络与本机 IPC 🧰 Qt 工程化与陷阱 📚 目录 🏠 主页 Qt 核心机制完全指南 — QObject 对象树 · 信号槽与 moc · 元对象系统 · 事件循环 — Kavin Tech Notes · 2026 ↑"}]},{"u":"desktop-gui/qt_networking_ipc.html","t":"Qt 网络与本机 IPC 完全指南","c":"桌面 GUI / Qt","s":[{"a":"","h":"","x":"Qt 网络与本机 IPC 完全指南 · QTcpSocket / 分帧 / QNetworkAccessManager / QSslSocket / QProcess / 重连状态机 Kavin Tech Notes ← 主页 目录 20 min ◐ Qt 网络与 IPC Qt 的网络模型 QTcpSocket / QTcpServer 分帧：粘包与半包 UDP 与设备发现 HTTP：QNetworkAccessManager TLS 与证书校验 本机 IPC：进程 / 管道 / 共享内存 实战：设备长连接状态机 面试题集（12 道） 9.1 基础 9.2 中级 9.3 高级 Desktop GUI · Qt Network & IPC · 2026 Qt 网络与本机 IPC 完全指南 Qt 把 socket 包成了信号槽，代价是 很多人从此不知道底下发生了什么 ——照样写出粘包 bug、照样在 UI 线程里 waitForReadyRead 把界面冻住。本篇覆盖异步模型、TCP 分帧、HTTP、TLS、本机 IPC，落到一个抗断网的 设备长连接状态机 。 核心难度 ★★★★☆ 工程实用度 极高 阅读时长 ~20 min 前置 TCP/IP · Qt 事件循环 QTcpSocket · 分帧 QNetworkAccessManager QSslSocket · 证书 QProcess · 共享内存 没写过 Qt？ 先读 Qt 零基础全景入门 ，再回来看这里的协议与重连细节。"},{"a":"s1","h":"Qt 的网络模型","x":"01 Qt 的网络模型 异步在哪，边界在哪 你的槽函数：connect(dev, &X::readyRead, this, &Y::onData) Qt 封装层（全部挂在同一个事件循环上） QTcpSocket 跨机器 · 字节流 无消息边界 QUdpSocket 跨机器 · 数据报 有边界，会丢 QNetworkAccessMgr HTTP · 请求响应 含 TLS / 重定向 QLocalSocket 本机 · 字节流 无消息边界 QSharedMemory 本机 · 大块内存 需外部加锁 操作系统 内核 TCP/IP 协议栈 Qt 用 poll(2) 拿就绪通知，O(n) 于 fd 数 Unix socket / 命名管道 共享内存段 + 信号量 左三个能跨机器、右两个只在本机； 五个里只有 QUdpSocket 自带消息边界 ，其余都要自己分帧（§3） QProcess 是第六条路：管道接子进程 stdio，适合「调外部工具拿结果」而不是持续通信 六条路，按「跨机器 / 本机」和「有无消息边界」两维分类 Qt 的网络 API 是「事件循环驱动的异步 IO」 ：socket 的文件描述符被注册进当前线程的事件分发器，可读时事件循环发出 readyRead() 信号，你在槽里取数据。 没有独立的 IO 线程 ——它和你的 UI 事件共用同一个循环。 裸 socket 是 自己守着电话 ：不停问「有人打来吗」（poll），或干脆守在话筒边（阻塞 recv）。Qt 是 装了台答录机 ：来电时响铃通知你。方便，但答录机和门铃、闹钟共用同一个「你」—— 接一通长电话，门铃就没人应 。 网卡收到 TCP 段 内核接收缓冲 Recv-Q 变非空 poll() 返回 该 fd POLLIN Qt 读进 自己的读缓冲 readyRead() 同步调你的槽 readyRead 的语义：「读缓冲里多了些字节」——多少字节、够不够一条消息，它都不知道 这一整条链在同一个线程里跑完 上一个槽没返回，下一次 poll 就不会发生 —— 数据只是堆在内核缓冲里 推论一：槽里做耗时计算 → Recv-Q 堆积 → TCP 窗口收缩 → 对端发送变慢 ，表现为「偶尔收不到数据」 推论二：一次 readyRead 对应的字节数 完全不可预测 ，所以必须累积缓冲（§3），不能 readAll 后直接 parse 从网卡到槽函数，中间四跳都在同一个线程里 Qt：事件循环统一分发 同一个线程的事件循环（poll 一组 fd） socket fd 可读 定时器 到期 鼠标 / 重绘 窗口事件 readyRead() / timeout() / paintEvent() 逐个同步调用你的槽 任何一个槽跑得久，其它全部延迟 裸 epoll 服务端：IO 独占线程 IO 线程：epoll_wait（O(1) 就绪通知） 上万个 fd 只返回就绪的 worker 线程池 处理业务 IO 与业务解耦，可独立扩容 适合 C10K 以上 Qt 的强项是把 IO 与 GUI 统一到一个循环；短板是 fd 多了以后 poll 的 O(n) 开销 维度 Qt Network 裸 socket + epoll / Asio 底层多路复用 poll(2) （Linux 上经 GLib 的 GMainContext） epoll / io_uring / IOCP 复杂度 O(n) 于 fd 数量 O(1) 就绪通知 适用连接数 几十到几百 （客户端、小型服务） 上万（C10K+） 与 GUI 集成 天然 ，同一循环 需要跨线程桥接 写法 信号槽，无回调地狱 回调 / 协程 TLS 内置 QSslSocket 自己接 OpenSSL 选型结论 ：连几台设备用 Qt Network；要扛上万连接用 Asio 或裸 epoll，见 C++ 异步网络框架完全指南 、 I/O 多路复用 。 ❌ waitForReadyRead()：函数不返回，事件却在继续跑 ✅ 信号槽：函数立刻返回，数据来了再进槽 onButtonClicked() { sock->waitForReadyRead(3000); … 内部起一个局部 QEventLoop 你的调用栈停在这里 —— 但事件循环照样分发 重绘 · 点击 · 定时器 · 甚至「关闭窗口」 重入 同一个槽被再次进入 状态机错乱 use-after-free 窗口在等待期间被关 返回后访问已析构的 this 和 processEvents() 是同一类风险 onButtonClicked() { sock->write(req); } ← 立即返回 控制权交回事件循环 界面继续响应，进度条继续转 对端回数据 → 事件循环调 onReadyRead() 状态存在成员变量里，不存在调用栈上 对象被删 → 连接自动断开，槽不会被调 超时用 QTimer 表达，不用等待表达 唯一代价：逻辑被拆成几个槽 waitForXxx 不是「暂停」，是「一边阻塞你、一边放行别人」 waitForReadyRead() / waitForConnected() 在 UI 线程里是禁区 ，理由见上图。它们唯一的合法用途： 在没有 GUI 的工作线程里写同步风格的协议交互 。 网络线程（有自己的事件循环） QTcpSocket 属于这个线程 readyRead → 分帧 → 解析 emit frameReady(Sample s) 参数必须可拷贝并 qRegisterMetaType UI 线程（main） 事件循环取出排队的调用 在自己线程里执行槽 onFrame(Sample) → 更新曲线 / 标签 这里才允许碰 QWidget Queued 值拷贝入队 ✗ 直接调 label->setText() 线程亲和性、Auto/Queued 的判定规则见 Qt 并发与跨线程 §3 ；本篇只强调一点： 自定义类型忘了 qRegisterMetaType，Qt 只打一行 warning 然后静默丢弃这次调用 —— 表现为「信号发了、槽没跑」 「Qt 界面 + 高并发网络」的标准形态：网络独立线程，只用 Queued 信号过桥（ 跨线程信号槽 ）"},{"a":"s2","h":"QTcpSocket / QTcpServer","x":"02 QTcpSocket / QTcpServer 信号时序与必调的几个选项 客户端：信号时序与三条错误分支 正常路径（每个信号都是异步的，connectToHost 立刻返回） connectToHost 立刻返回 Connecting SYN 已发出 connected() 此时才能设选项 readyRead() × N 次数不可预测 disconnected() FIN 或 abort 三条错误分支 —— 各自的处理完全不同，不能一律「重连」 ConnectionRefusedError 对端 IP 在、端口没人听 来得很快（收到 RST） → 服务没起，退避重连有意义 errorOccurred SocketTimeoutError SYN 无人应答（丢包/防火墙） 系统栈可能拖几十秒才报 → 必须自己起 QTimer 兜底 见 §8 状态机 RemoteHostClosedError 对端主动 FIN 仍会再发 disconnected() → 两个信号都会来，别重连两次 用状态位去重 最隐蔽的一条：拔网线既不触发 errorOccurred 也不触发 disconnected TCP 栈不知道对端没了，socket 一直停在 ConnectedState —— 界面上「已连接」，实际早就断了 所以判断「还活着」只能靠 应用层心跳 ，不能靠 state() 或任何 socket 信号 四个信号 connected / readyRead / disconnected / errorOccurred 就是全部；难的是最后那一格 选项 作用 什么时候必须设 LowDelayOption （TCP_NODELAY） 关闭 Nagle 算法，小包立即发送 几乎总是 ：控制指令、心跳、请求-响应式协议 KeepAliveOption 启用 TCP keepalive 探测 长连接。但默认间隔是 系统级的 2 小时 ，太慢，必须配应用层心跳 ReceiveBufferSizeSocketOption setReadBufferSize() 前者是内核收缓冲，后者是 Qt 层 读缓冲上限（0 = 无限） 高吞吐（图像流）调大内核缓冲防丢包；给 Qt 层设上限即得到背压，读慢了 TCP 窗口自动收缩 TCP keepalive 不是应用层心跳的替代品。 Linux 默认 tcp_keepalive_time 是 7200 秒；而且它只探测「TCP 连接还在吗」，探测不到「对端进程假死但 TCP 栈还活着」。 必须有应用层心跳 ，1–5 秒一次。 服务端：为什么取连接要用 while 一轮事件分发里到了 4 个连接，Qt 只发 1 次 newConnection 内核 accept 队列 conn #1 conn #2 conn #3 conn #4 newConnection() 只发一次 信号会被合并 ❌ 只调一次 nextPendingConnection() #1 被处理，#2–#4 留在队列里干等下一个连接到来 低负载测试完全正常；压测时表现为「客户端连上却收不到响应」 队列满（backlog）之后新连接直接被内核丢弃 ✅ while (auto* s = nextPendingConnection()) 取到 nullptr 才停；顺手 connect(s, disconnected, s, deleteLater) QUdpSocket 同理：while (hasPendingDatagrams()) 要分发到工作线程时，重写 incomingConnection(qintptr fd) 而不是用信号 拿到裸 fd → 造一个无 parent 的 handler → moveToThread → Queued 调 setup() 硬约束：QTcpSocket 必须在它所属线程里 setSocketDescriptor()，在主线程建好再搬过去是 UB Qt 服务端最经典的漏写：把 while 写成了一次调用"},{"a":"s3","h":"分帧：粘包与半包","x":"03 分帧：粘包与半包 TCP 是字节流，不是消息流 粘包 / 半包 ：TCP 只保证「字节按序到达」， 不保证消息边界 。发送方连发 3 条 10 字节消息，接收方可能一次 readyRead 收到 30 字节（粘包），也可能分 5 次分别收到 7/8/6/4/5 字节（半包）。 readyRead 只是说「有数据了」，从不承诺「有一条完整消息了」。 TCP 像 传送带上的散装货 ：放上去的是三个包裹，传送带只保证「按顺序过来」，中间的空隙早就没了。想还原成包裹，必须 自己贴标签 ——每件货前写清「我有多长」（长度前缀）。 发送端：三次 write，你以为发了三条消息 write(A) 10B write(B) 10B write(C) 10B ← 边界只存在于你的代码里 TCP 连接 = 一条没有分隔符的字节流 内核只承诺这 30 个字节按序、不丢、不重 —— 「哪里是一条消息」这件事被彻底丢掉了 接收端：readyRead 触发几次、每次多少字节，取决于 MTU、Nagle、窗口、调度 可能 ①：一次收 30B A B C 只 parse 一次 → 丢了 B 和 C 可能 ②：切成 7/8/6/9 7B 3+5B 5B 10B 碎片不对齐 → parse 直接失败 唯一正确的心态 readyRead 只是「有新字节」 攒进缓冲，循环问「够一帧了吗」 不够就退出，等下一次 本地回环、小数据量时 ①② 都不出现，所以错误代码「看起来能跑」 现场一 · 粘包：小指令连发 现场二 · 半包：单帧超过 MTU for (auto& c : cmds) sock->write(c); ← 循环里连发 3 条 8B 指令 8B 8B 8B Nagle 或内核合并 一个 24B 的段 对端一次 readyRead 收到 24B。只 parse 头 8B 的代码会 静默丢掉后两条指令 —— 现场表现为「命令偶尔不生效」 write 一帧 4000B 的图像行（> MTU 1500） 一帧 4000B 被 MTU 切开 1460B 1460B 1080B 至少 3 次 readyRead。「收到就解析」的代码在第一次就 拿着 1460B 去解 4000B 的帧 —— 报「数据损坏」然后断链 两种现场方向相反，但解药是同一个：累积缓冲 + 循环解析 等头 buf.size() < 4 ? 校验长度 len > kMaxFrame ? 等 body size() < 4+len ? 交付并消费 remove(0, 4+len) abort() 断链，不重同步 ≥4 合法 超上界 齐了 继续下一帧（关键：是循环，不是一次） 任一「不够」→ 直接 return，等下一次 readyRead 再来 缓冲总量也要设上限：对端只发 4 字节头、永不发 body 时， 这个状态机会一直停在「等 body」，缓冲无限增长 四个状态、一条回边。下面这段代码就是它的逐字翻译 ❌ 假设一次收到一条完整消息 void onReadyRead() { QByteArray data = m_sock->readAll(); Msg m = parse(data); // 半包 → 解析失败 handle(m); // 粘包 → 只处理了第一条 } // 症状：局域网测试一切正常， // 现场跨交换机 / 大数据量时随机丢消息 ✅ 累积缓冲 + 循环解析 void onReadyRead() { m_buf += m_sock->readAll(); // 先攒 for (;;) { if (m_buf.size() < 4 ) break ; // 头都不够 quint32 len = qFromBigEndian<quint32>( reinterpret_cast < const uchar*>(m_buf.constData())); if (len > kMaxFrame) { // 防御：长度字段被污染 m_sock->abort(); return ; } if (m_buf.size() < 4 + len) break ; // body 还没齐 handle(m_buf.mid( 4 , len)); // 整帧到手 m_buf.remove( 0 , 4 + len); // 消费掉 } } if (len > kMaxFrame) abort(); 不是可选的。 长度前缀直接来自网络，对端发一个 0xFFFFFFFF 你就会去分配 4 GB——轻则 OOM，重则成为 DoS 入口。 任何从网络读来的长度字段都要先做上界检查 ，见 C++ 安全与硬化指南 。 用 QDataStream 做序列化 写端 · 上位机 Qt 5.15 out << id << name << th 未调 setVersion → 用 Qt_5_15 网络上的字节 大端序（= 网络序） 无自描述、无版本标记 读端 · 设备固件 Qt 5.9 in >> id >> name >> th 未调 setVersion → 用 Qt_5_9 同一串字节、两套解码规则 —— 错得不彻底，才最难查 ✓ quint16 / double 正确 定长基本类型编码从未变过 于是「大部分字段是对的」 ✗ QString / 容器错位 长度前缀与编码在版本间变过 读出乱码，并把后续字段全带偏 status() 不一定报错 字节数恰好够时仍返回 Ok 不抛异常，只设状态位 解法只有一句： 协议两端都显式 setVersion() 钉死同一个版本号 ，并写进协议文档，而不是依赖编译时的 Qt 版本 「大部分字段对，某个字符串偶尔乱码」——这个症状几乎总是漏了 setVersion() // 两端各写一遍这四行；版本号进协议文档，不要跟着编译期的 Qt 版本漂 QDataStream out(&payload, QIODevice::WriteOnly); out.setVersion(QDataStream::Qt_5_15); // ★ 漏掉这行就是上图的故事 out << quint16(cmdId) << deviceName << threshold; QDataStream in(body); // body = §3 分帧取出的整帧 in.setVersion(QDataStream::Qt_5_15); in >> cmd >> name >> th; if (in.status() != QDataStream::Ok) { /* 损坏：丢弃整帧，不要试图重同步 */ } QDataStream 是 Qt 私有格式，Python/C# 侧解析不了；跨语言请用 明确定义的二进制布局 。分帧本身与语言无关，通用做法见 Socket 工程要点 。"},{"a":"s4","h":"UDP 与设备发现","x":"04 UDP 与设备发现 工业现场的「找设备」环节 广播发现：上位机喊一嗓子，设备各自应答 上位机 writeDatagram \"DISCOVER\" → :9999 广播 / 组播 255.255.255.255 或 239.255.0.1 相机 · 应答 PLC · 应答 测距仪 · 丢了 datagram 的性质 ✓ 自带消息边界 一个包 = 一次接收，不粘 ✗ 会丢、会乱序、会重复 所以要重发 3 次 设备端对重复请求幂等 头号现场问题：设备明明在线却发现不了 工业上位机常插三张网卡： eth0 相机网 eth1 PLC 网 eth2 办公网 广播只从「默认路由」那张出去 → 只有办公网收到了 DISCOVER ✅ 遍历网卡，逐张发 for (auto& ifc : QNetworkInterface::allInterfaces()) 对每张 up 且非 loopback 的网卡分别 bind 该地址后再发 组播同理，要显式 setMulticastInterface(ifc)，不能靠默认 UDP 省掉了分帧，换来的是丢包容忍和「从哪张网卡出去」这两个新问题 收 datagram 同样要 while (udp->hasPendingDatagrams()) 取干净，理由和 §2 的 nextPendingConnection 一样。"},{"a":"s5","h":"HTTP：QNetworkAccessManager","x":"05 HTTP：QNetworkAccessManager 调 REST 接口的标准姿势 一个 QNAM 实例（全应用共用），内部维护连接池 QNetworkAccessManager · 每个 host 一组 keep-alive 连接，反复复用 nam->post(req) 立刻返回 reply* 此时还没发出去 取连接 池里有 → 直接用 没有 → TCP+TLS uploadProgress downloadProgress 可选，做进度条 3xx 重定向 Qt 自动跟随 但不该降级到 http finished() 成功与失败都走这里 只发一次 finished 槽里必须按这个顺序做三件判断 ① deleteLater() 第一行就写，别放最后 reply 没有 parent，不删就漏 delete 会崩：在自己信号里删自己 ② error() 传输层：DNS / 拒绝 / 超时 也包含 4xx/5xx 但只看它分不出是哪一种 ③ HTTP 状态码 HttpStatusCodeAttribute 401 要去刷 token 404 是业务不存在，别重试 没有 ①：稳定泄漏。没有 ③：把「登录过期」当成「网络不好」，用户看到的提示永远是错的。 QNAM 帮你做了连接池、TLS 和重定向； deleteLater 与状态码判断它不管 // nam 是全应用唯一的那一个实例，不要在这里 new QNetworkRequest req{QUrl( \"https://api.example.com/v1/inspections\" )}; req.setHeader(QNetworkRequest::ContentTypeHeader, \"application/json\" ); req.setAttribute(QNetworkRequest::RedirectPolicyAttribute, QNetworkRequest::NoLessSafeRedirectPolicy); // 跟随重定向，但不降级到 http req.setTransferTimeout( 10000 ); // Qt 5.15+，必设 QNetworkReply* reply = nam->post(req, QJsonDocument(body).toJson()); connect(reply, &QNetworkReply::finished, this , [reply, this ]{ reply->deleteLater(); // ① 第一行 if (reply->error() != QNetworkReply::NoError) { // ② 传输层 emit failed(reply->errorString()); return ; } const int code = reply->attribute( // ③ 业务层 QNetworkRequest::HttpStatusCodeAttribute).toInt(); if (code < 200 || code >= 300 ) { emit failed(QString( \"HTTP %1\" ).arg(code)); return ; } emit succeeded(QJsonDocument::fromJson(reply->readAll())); }); 坑 后果 正确做法 每次请求 new 一个 QNAM 连接池失效，每次重建 TCP + TLS 握手 全应用一个实例 reply 生存期没管好 不删 → 稳定泄漏（reply 没有 parent）；用 delete → 在自己信号里删自己，崩溃 finished 第一行 deleteLater() 不设超时 Qt 5.15 之前 没有默认超时 ，网络黑洞时永久挂起 setTransferTimeout() ；老版本用 QTimer + abort() 跨线程使用 QNAM reply 与 manager 必须同线程，否则 UB 每个线程一个，或统一在一个线程用 协议本身（keep-alive、chunked、HTTP/2 多路复用、QUIC）见 HTTP / HTTPS 协议完全指南 ；接口怎么设计见 API 设计 。"},{"a":"s6","h":"TLS 与证书校验","x":"06 TLS 与证书校验 最容易被「先跑通再说」毁掉的一节 connectToHost Encrypted() TCP 三次握手 还是明文 ClientHello → ← 证书链 + 密钥交换 Qt 校验证书链 CA 可信？CN/SAN 对？过期？ encrypted() 此后才能安全收发 全部通过 任一项不通过 → emit sslErrors(errs) 握手在这里暂停，等你的槽决定 ❌ 槽里裸调 ignoreSslErrors()（无参） 等于把上面那个「校验证书链」的格子整个划掉 加密还在， 身份认证没了 ：任何人出示自签证书都能冒充 比明文 HTTP 更危险——它给人「已经加密了」的错觉 ✅ 不连 sslErrors，让它按默认规则失败 内网自签证书的正解：把自签 CA 加进 caCertificates 校验路径不变，只是信任源多了一个 实在要放过，用 带参版本 只放过逐条检查过的那批 sslErrors 是握手中间的一个决策点，不是一条日志 写法 实际含义 能不能进主干 ignoreSslErrors() 无参 放过一切， 包括未来 Qt 新增的错误类型 ❌ 一旦写进去几乎没人再删 ignoreSslErrors(errs) 带参 只放过你逐条 if 判断过的那一批 ⚠️ 可接受，前提是真的逐条判了 自签 CA 进 caCertificates + VerifyPeer 校验流程不变，只是多了一个信任根 ✅ 内网设备的标准解法 setLocalCertificate + setPrivateKey 双向认证（mTLS），服务端也校验你 ✅ 高安全要求场景 部署时确认目标机器上有 OpenSSL 运行库。 QSslSocket::supportsSsl() 返回 false 是现场「HTTPS 全挂、HTTP 正常」的典型原因，Windows 上通常是漏拷 libssl-*.dll / libcrypto-*.dll 。 握手细节、证书链验证、SNI/ALPN 见 TLS / SSH / 证书 ；这里只讲 Qt 侧的 API 陷阱。"},{"a":"s7","h":"本机 IPC：进程 / 管道 / 共享内存","x":"07 本机 IPC：进程 / 管道 / 共享内存 Qt 对操作系统 IPC 的封装 Qt 类 底层机制 消息边界 适合传什么 主要坑 QProcess fork+exec，管道接 stdio 无 调外部工具拿结果 不读输出会把子进程 卡死 QLocalSocket / QLocalServer Unix domain socket / 命名管道 无，要自己分帧 本机的控制消息 §3 的坑一个不少 QSharedMemory 共享内存 / 文件映射 无（就是一块内存） 大块数据 （图像帧） 无跨进程同步；崩溃后残留 QSystemSemaphore POSIX/SysV 信号量 — 跨进程互斥 / 计数 同样崩溃残留 TCP over localhost 回环 socket 无，要自己分帧 将来可能跨机器 比 UDS 慢，代码完全一致 QProcess 的两条红线 永远不要用字符串拼接构造命令行。 start(\"tool \" + userInput) 在 Windows 上会被 shell 语义解析，输入里的 & 、 | 、 > 就成了命令注入。用 setProgram() + setArguments(QStringList) ，参数以数组交给 OS，不经过 shell——就是 system() vs execv() 那个区别。 不读 stdout/stderr 会把子进程卡死。 管道缓冲（Linux 上约 64 KB）写满后子进程的 write 阻塞，而你在等 finished ——双方互等。要么持续读，要么重定向到 QProcess::nullDevice() 。 本机 IPC 的标准形态：控制面 + 数据面分开 进程 A · 采集 进程 B · 界面 控制面 · QLocalSocket（小消息） {\"slot\":3,\"w\":4096,\"h\":3000,\"fmt\":\"BGR\"} 有序 · 有连接语义 · 对端崩溃能感知 它是字节流 —— 一样要长度前缀分帧（§3） 数据面 · QSharedMemory（大块，零拷贝） slot 0 slot 1 slot 2 slot 3 N 个槽位的环形缓冲：A 写下一格，B 读刚就绪的那格 QSystemSemaphore（跨进程） shm.lock() 只是本进程内互斥，跨进程一点用都没有 单实例守护 ✗ 用 shm.create() 成功判断 崩溃后段残留 → 永远说 「已有实例」，只能重启机器 ✓ QLocalServer::listen(name) 崩溃残留 Unix 上共享内存段与信号量 是 内核持久 的，进程死了不回收 清理手法：attach() 后 detach() 让引用计数归零，再 create() socket 反过来 由 OS 自动回收 ，所以「谁先抢到名字」这类判断一律交给 QLocalServer，不要交给共享内存 大数据量 IPC 的通用模式：数据走共享内存，「第几号槽位好了」走消息通道 // 数据面：崩溃残留清理 + 跨进程加锁，是 QSharedMemory 唯一容易写错的两处 QSharedMemory shm( \"vision_frame_buffer\" ); if (!shm.create(kSlotBytes * kSlots) && shm.error() == QSharedMemory::AlreadyExists) { shm.attach(); shm.detach(); // 让内核引用计数归零（上次崩溃留下的段） shm.create(kSlotBytes * kSlots); } QSystemSemaphore sem( \"vision_frame_sem\" , 1 , QSystemSemaphore::Create); sem.acquire(); // ★ 不是 shm.lock()：那个只锁本进程 memcpy( static_cast <uchar*>(shm.data()) + slot * kSlotBytes, frame.bits(), kSlotBytes); sem.release(); 数据量其实不大（几 KB 的结果 JSON）时，共享内存的复杂度完全不值得，直接走 QLocalSocket 。操作系统层面的 IPC 全景见 Linux 多进程与 IPC 完全指南 。"},{"a":"s8","h":"实战：设备长连接状态机","x":"08 实战：设备长连接状态机 把前面的东西拼成一个能上产线的东西 设备重启、交换机抖动、网线被叉车碾过—— 「连上就一直连着」的假设必然失败 ，连接本身必须建模成状态机。 Disconnected 初始 / 已断开 Connecting 带超时 Connected 心跳中 Backoff 1s→2s→4s…30s Closing 主动停机 open() connected 超时 / 拒绝 退避到期 心跳超时 / disconnected close() 每次成功连接后重置退避计数；退避上限封顶（如 30s），避免设备重启期间把网络打满 Connected 态内部还有子状态：心跳发出 → 等应答 → 连续 N 次无应答则判定断线 Closing 是显式态：区分「我要停」与「意外断」，前者不触发重连 五个状态、一条退避回路。Closing 与 Disconnected 必须分开，否则「关闭程序」会触发重连 动手感受：断线重连与指数退避 观察退避间隔如何翻倍到上限，以及连接恢复后计数如何被重置。 Disconnected Connecting Connected Backoff open() 拔网线（设备失联） 插回网线 close() // 整个状态机里真正值得抄的就这四处；其余是样板代码 void DeviceLink::doConnect() { setState(State::Connecting); m_sock->abort(); // 清掉上次的残留状态 m_sock->connectToHost(m_host, m_port); m_connectTimer.start(kConnectTimeoutMs); // ④ 系统栈的超时可能几十秒 } void DeviceLink::onConnected() { m_connectTimer.stop(); m_sock->setSocketOption(QAbstractSocket::LowDelayOption, 1 ); m_backoffMs = kBaseBackoff; // ① 成功后重置退避 m_missedBeat = 0 ; m_hbTimer.start(kHeartbeatMs); } void DeviceLink::onDisconnected() { m_hbTimer.stop(); if (m_closing) { setState(State::Disconnected); return ; } // ③ 主动停不重连 setState(State::Backoff); const int jitter = QRandomGenerator::global()->bounded(m_backoffMs / 4 + 1 ); m_retryTimer.start(m_backoffMs + jitter); // ② 抖动，避免惊群 m_backoffMs = qMin(m_backoffMs * 2 , kMaxBackoff); } 这四处标号正是面试时该主动讲的四点，展开见 §9.3 第 10 题 。 心跳判定用「连续 N 次未应答」，不是「一次超时就断」 ——偶发丢包很正常，单次就重连会让连接反复抖动。典型参数：2 秒一次、连续 3 次判死。另外 QTimer 精度依赖事件循环，UI 卡顿时会延迟，所以 判定要基于时间戳差值而非回调次数 。"},{"a":"s9","h":"面试题集（12 道）","x":"09 面试题集（12 道） 按难度分层，先自测再对照"},{"a":"s9-1","h":"9.1 基础（必答）","x":"9.1 基础（必答） 点击每道题展开参考答案（先自测，再对照）。 基础 什么是 TCP 粘包？ readyRead 触发时能假设收到了一条完整消息吗？ 不能。TCP 是 字节流 协议，只保证字节按序、不丢不重， 不保证消息边界 。发送方三次 write 的数据，接收方可能一次全收到（粘包），也可能分多次收到半条（半包）。 readyRead 的语义只是「缓冲区里有新数据了」。正确处理方式是 累积缓冲 + 循环解析 ：把新数据追加到成员缓冲区，然后在循环里反复尝试「够不够一个完整帧」，够就取走一帧继续，不够就退出等下次。 为什么本地测试发现不了 本地回环、小数据量时，一次 write 通常就对应一次 readyRead，错误代码「看起来能跑」。一到现场跨交换机、数据量上来，问题立刻暴露。 基础 为什么不能在 UI 线程调用 waitForReadyRead() ？ 因为它内部会 跑一个局部的 QEventLoop 直到条件满足或超时。两个后果： 它会 阻塞你的函数 ——期间界面不响应，网络慢就是卡死几秒。 更隐蔽的是它 继续分发其它事件 ，带来和 processEvents() 相同的重入与 use-after-free 风险：用户可能在这期间关闭了窗口，函数返回后你继续访问成员变量。 UI 线程里应该用信号槽的异步写法。 waitForXxx 的合法用途是 在没有 GUI 的工作线程里写同步风格的协议交互 。 基础 用 QNetworkAccessManager 发请求，有哪几件事必须做？ 全应用共用一个 QNAM 实例 ——它内部维护连接池，每次 new 一个就等于每次重建 TCP + TLS 握手。 在 finished 槽里 reply->deleteLater() ——reply 没有 parent，不删就泄漏；而且必须用 deleteLater 不能用 delete （正在自己的信号里删自己会崩）。 设超时 ——Qt 5.15 之前 QNAM 没有默认超时，遇到网络黑洞会永久挂起。用 setTransferTimeout() ，老版本用 QTimer + abort() 。 既判 error() 也判 HTTP 状态码 ——只看 error 会漏掉需要区分处理的 4xx/5xx 语义。 QNAM 和它创建的 reply 必须在同一线程 。 基础 ignoreSslErrors() 有什么危害？内网自签证书应该怎么处理？ 无参的 ignoreSslErrors() 会忽略 一切 证书错误，包括「证书不是可信 CA 签发的」「域名不匹配」「证书已过期」。结果是： 加密还在，但身份认证没了 ——任何中间人出示一张自签证书就能冒充服务器，客户端照单全收。这比明文 HTTP 更危险，因为它给人一种「已经加密了」的虚假安全感。 正确做法 ：把设备/内网服务的自签 CA 证书打进程序资源，加入 QSslConfiguration 的信任列表，并保持 VerifyPeer ： cfg.setCaCertificates(cfg.caCertificates() + QSslCertificate::fromPath( \":/certs/company-ca.pem\" )); cfg.setPeerVerifyMode(QSslSocket::VerifyPeer); 实在要忽略，也只能用 带参版本 忽略你逐条检查过的那一批错误。"},{"a":"s9-2","h":"9.2 中级（区分熟练度）","x":"9.2 中级（区分熟练度） 中级 设计一个二进制协议的分帧方案，说明要防御哪些异常输入。 方案 ：4 字节大端长度前缀 + 变长 body。可选再加 2 字节魔数用于重同步、2 字节版本号、末尾 4 字节 CRC。 接收侧算法 ：新数据追加到缓冲 → 循环｛缓冲不足 4 字节则退出；读长度；长度超上限则断链；缓冲不足 4+len 则退出；取出整帧、消费掉、继续｝。 必须防御的输入 ： 超大长度字段 攻击者发 0xFFFFFFFF ，你若直接按它分配就是 4 GB 内存申请，OOM 或 DoS。 必须有 kMaxFrame 上界检查 。 长度为 0 若代码里有「消费 4+len 字节」的逻辑而 len 可以为 0，配合某些写法会导致死循环空转。 缓冲无限增长 对端只发头不发 body，你的累积缓冲会一直涨。要给缓冲总量也设上限。 字节序与对齐 不要直接 reinterpret_cast 成结构体读——对齐和字节序都不可移植。用 qFromBigEndian 逐字段读。 中级 使用 QDataStream 做网络序列化，有什么必须注意的兼容性问题？ 必须显式调用 setVersion() 。 QDataStream 的默认版本随 Qt 版本变化，而不同版本对 QString 、容器、 QVariant 的编码格式并不相同。上位机用 Qt 5.15、设备固件用 Qt 5.9，不钉版本就是两边各说各话——表现往往是「大部分字段正确，某个字符串偶尔乱码」，极难排查。 其它注意点：默认字节序是 大端（网络序） ，与主机序不同要心里有数；浮点精度默认是双精度，可用 setFloatingPointPrecision 控制；读完后要检查 in.status() 是否为 Ok ，损坏数据不会抛异常只会设状态位。 选型边界 QDataStream 是 Qt 私有格式 ，Python/C# 侧无法解析。跨语言、跨团队、需要长期演进的协议应该用 Protobuf 或明确定义的字节布局；它的甜蜜区是「两端都是自己写的 Qt 程序」。 中级 为什么处理 newConnection 时要用 while 循环取连接？ 因为一次 newConnection 信号可能对应 多个 待处理连接。Qt 在一轮事件分发里如果 accept 到了若干连接，不会为每个都单独发一次信号（信号可能被合并）。只调用一次 nextPendingConnection() ，剩下的连接就留在队列里，直到下一个连接到来才被处理。 后果是 高负载时连接堆积、客户端超时 ——低负载测试完全正常，压测才暴露。同样的道理适用于 QUdpSocket ：要用 while (hasPendingDatagrams()) 把 datagram 取干净。 中级 用 QProcess 调外部程序时，为什么会出现「子进程单独跑很快，被程序调用就卡住」？ 因为 没有读 stdout/stderr 。子进程的输出写进管道，管道缓冲区（Linux 上通常 64 KB）写满后子进程的 write 会阻塞；而父进程在等 finished 信号——双方互等，永久卡死。 解决 ：连上 readyReadStandardOutput / readyReadStandardError 持续读走；或者明确不需要输出时把通道重定向到 QProcess::nullDevice() 。 另一个常见错误 用字符串拼接构造命令行（ start(\"tool \" + userInput) ）会引入命令注入。应该用 setProgram() + setArguments(QStringList) ，参数以数组传给 OS，不经过 shell。"},{"a":"s9-3","h":"9.3 高级（体现深度）","x":"9.3 高级（体现深度） 高级 Qt 的网络 IO 适合做高并发服务端吗？如果一个 Qt 应用必须扛上万连接，架构怎么设计？ 不适合。 Qt 的事件分发底层是 poll(2) （Linux 桌面上走 GLib 的 GMainContext，同样基于 poll），复杂度是 O(n) 于 fd 数量 ：每轮都要把整个 fd 数组交给内核、返回后线性扫描。几百个连接没问题，上万就会在 poll 上耗掉大量 CPU。而且网络事件与 GUI 事件共用一个循环，任何一个慢槽都会拖累全部。 架构方案 ：把网络层从 Qt 事件循环里剥出来——独立线程跑 Asio / 裸 epoll / io_uring，用自己的线程池处理业务；只在需要更新界面时，通过 QMetaObject::invokeMethod 或 Queued 信号把结果送回 UI 线程。这样 GUI 与网络各自用最适合的模型，边界清晰。 边界判断 连接数在 几百以内 、且每个连接流量不大时，Qt 自带的够用且省事；一旦要考虑 C10K，就不该在 Qt 的循环里解决。详见 异步网络框架指南 。 高级 设计一个能抗住现场断网的设备长连接，说明状态机和关键参数。 五个状态 ：Disconnected / Connecting / Connected / Backoff / Closing。Closing 必须与 Disconnected 分开——否则「用户点退出」会被当成意外断开而触发重连，程序关不掉。 四个关键设计 ： 应用层心跳 TCP keepalive 默认 2 小时，且探测不到「进程假死但 TCP 栈还活着」。必须自己发心跳，典型 2 秒一次， 连续 3 次无应答 才判定断线（单次超时就断会导致连接反复抖动）。 指数退避 + 抖动 1s → 2s → 4s …封顶 30s，并加随机抖动。抖动很重要：多台上位机同时重连会把刚恢复的设备再次打挂（惊群）。 成功后重置退避 忘了重置的话，一次长时间断网之后即使网络恢复，也要等满 30 秒才连上。 自己的连接超时 系统 TCP 连接超时可能数十秒（SYN 重传），必须自己起一个 QTimer ，超时就 abort() 转入退避。 时间判定 心跳超时判定要基于 时间戳差值 而非回调次数——QTimer 精度依赖事件循环，UI 卡顿时定时器会延迟，按次数算会误判。 高级 本机两个进程要传大图像帧，你会怎么选 IPC 方案？ 数据面用共享内存，控制面用消息通道 ——这是大数据量 IPC 的通用模式： 共享内存 （ QSharedMemory 或直接 shm_open + mmap ）放像素数据，避免几十 MB 的拷贝。做成 N 个槽位的环形缓冲，生产者写槽位、消费者读槽位。 QLocalSocket （Unix domain socket / 命名管道）只传「第 k 号槽位已就绪、尺寸格式如下」这样的小消息。它天然有序、有连接语义、对端崩溃时能感知。 同步 用 QSystemSemaphore 或共享内存里的 pthread 进程间互斥量。 QSharedMemory::lock() 只是本进程内的互斥， 不能跨进程用 。 崩溃残留 Unix 上共享内存段和信号量是 内核持久 的：进程崩溃后不会自动释放。要有清理逻辑（ attach() 后 detach() 让引用计数归零），或者启动时用固定 key 主动清理一次。 什么时候不该用共享内存 如果数据量其实不大（几 KB 的结果 JSON），共享内存的复杂度完全不值得——直接走 QLocalSocket 就行。共享内存的适用前提是「拷贝开销确实成为瓶颈」，先测量再上。IPC 机制的完整对比见 Linux 多进程与 IPC 指南 。 高级 Qt 客户端出现「偶尔收不到设备数据」，你会怎么排查？ 按 从外到内 的顺序切割，每一步都要有证据而不是猜测： 先确认包到没到主机 ： tcpdump -i any port 5000 -w cap.pcap ，用 Wireshark 看。如果抓不到，问题在设备侧或网络（交换机、VLAN、多网卡路由）——不要在应用代码里找。 包到了但应用没收到 ：查 socket 接收缓冲是否溢出（ ss -tmi 看 Recv-Q）。缓冲堆积说明 应用读得太慢 ——多半是 UI 线程被某个耗时槽占住了。 应用收到了但没处理 ：这就是分帧 bug。在 onReadyRead 里打印 bytesAvailable() 和累积缓冲长度，看是不是缓冲在持续增长（说明解析条件永远不满足，比如长度字段字节序搞反了）。 解析对了但槽没跑 ：跨线程时检查是否漏了 qRegisterMetaType ——自定义类型未注册时 Qt 只打一行 warning 然后 静默丢弃 。把 Qt 的 warning 接进日志系统，或临时设 QT_FATAL_WARNINGS=1 让它直接 abort 到调试器。 埋点先行 这类「偶发」问题事后排查成本极高。上线前就应该有三个指标： 每秒收帧数、解析失败计数、累积缓冲峰值 。有了这三个数，问题出现时看一眼监控就能定位到上面四层中的哪一层。参见 C++ 可观测性完全指南 。 ⬅️ Qt 并发与跨线程 ➡️ Qt 工程化与陷阱 🧭 全景入门 🌐 C++ 网络编程 📚 目录 🏠 主页 Qt 网络与本机 IPC 完全指南 — QTcpSocket · 分帧 · QNAM · QSslSocket · QProcess — Kavin Tech Notes · 2026 ↑"}]},{"u":"desktop-gui/qt_overview.html","t":"Qt 零基础全景入门","c":"桌面 GUI / Qt","s":[{"a":"","h":"","x":"Qt 零基础全景入门 · 是什么 / 解决什么问题 / 真实应用 / 关键模块 / 第一个程序 / 采集显示架构 Kavin Tech Notes ← 主页 目录 40 min ◐ Qt 全景入门 Qt 到底是什么 没有 Qt 会怎样 真实应用场景与产品 关键模块地图 第一个程序，逐行拆解 构建链：moc / uic / rcc 五大核心概念速览 实战：采集 → 显示架构 Widgets 还是 QML 新手十二坑 · 学习顺序 面试题集（12 道） 11.1 基础 11.2 中级 11.3 高级 Desktop GUI · Qt 入门 · 2026 Qt 零基础全景入门 写给 完全没碰过 Qt 的 C++ 工程师：Qt 到底是什么（不只是「一个 GUI 库」）、它替你挡掉了哪些平台差异、哪些行业在真实用它、十来个模块该学哪几个、一个窗口从 main() 到出现在屏幕上经过了什么、以及一个「设备采集 → 实时曲线」的小项目该怎么分层。读完这篇，你能看懂本系列后面四篇深水区在讲什么，也能判断手上的项目该不该选 Qt。 入门难度 ★★☆☆☆ 本系列第 0 篇 阅读时长 ~40 min 前置 只需 C++ 类与指针 是什么 · 做什么 模块地图 Hello World 逐行 项目分层架构"},{"a":"s1","h":"Qt 到底是什么","x":"01 Qt 到底是什么 一句话定义，再拆成三层 Qt （读作 \"cute\"）是一套用 C++ 写的 跨平台应用开发框架 ：一份源码，编译后能在 Windows / Linux / macOS / 嵌入式屏幕上跑出界面一致的原生程序。1991 年诞生于挪威 Trolltech，现由 The Qt Company 维护，当前主线是 Qt 6.x。 初学者最容易形成的误解是「Qt = C++ 的界面库」。 界面只是 Qt 的一个模块 。把它拆开看，Qt 实际上是三层东西叠在一起： 层 它提供什么 为什么当年需要它 ① 跨平台基础设施层 字符串 QString 、容器 QList / QHash 、文件与路径、线程、进程、定时器、网络、JSON/XML、配置存储、插件加载、国际化 1990 年代到 2010 年代，标准库既没有线程也没有网络、文件系统、正则、UTF-16 字符串。Qt 把这些一次补齐，且三大平台行为一致 ② 自建运行时层（最独特） 元对象系统 ：运行时反射、 信号槽 （对象间松耦合通信）、属性系统、按名字动态创建对象与调用方法 C++ 没有反射。而 GUI 天生需要「按钮被点了，通知所有关心的人」这种运行时动态绑定。Qt 用一个代码生成器 moc 把反射能力补上了 ③ UI 工具箱层 Qt Widgets （传统控件、CPU 绘制、桌面原生观感）与 Qt Quick / QML （声明式、GPU 加速、适合动效与触摸） 控件、布局、无障碍、输入法、高 DPI、主题——每一项自己实现都是巨量工作 把操作系统看成一座城市的 市政系统 （供水、供电、道路），那 Qt 就是建在其上的 一整套商场运营系统 ： 事件循环 是前台的呼叫队列（谁按了铃就排队、按顺序处理）； 对象树 是租户隶属关系（一个区域撤柜，它下面的摊位一并清退，不用你逐个去谈）； 信号槽 是内部广播线路（广播一响，订阅了这条线的部门自己反应，广播方根本不需要认识它们）。你写业务代码 = 在这套运营规范下开店； 好处是拎包入住，代价是必须守它的规矩 ——用纯 C++ 的习惯去动 Qt 的结构（比如自己 delete 一个有 parent 的控件、在别的线程里改界面），就是崩溃的主要来源。 顺手澄清几个「Qt 不是什么」 不是即时模式的绘图库 。Dear ImGui 那种「每帧重画整个界面」的模型和 Qt 完全不同：Qt 是 保留模式 ——控件是长期存在的对象，只在需要时重绘。 不是必须写 QML 。用 Qt Widgets 可以全程只写 C++，一行 QML 都不碰，这也是绝大多数工业软件的做法。 不排斥标准库 。 std::vector 、 std::unique_ptr 、算法库在 Qt 项目里完全可以正常用，两套容器可以共存（只在 API 边界上做转换）。 不只做桌面 。嵌入式屏（无窗口系统，直接画到 framebuffer 或 EGL）、车机、医疗仪器面板都是 Qt 的重要战场。 许可这件事必须一开始就知道 ：Qt 是双许可。 LGPLv3 允许闭源商业产品使用，但要求 动态链接 Qt 并允许终端用户替换 Qt 库； 商业许可 才可以静态链接（单文件固件的嵌入式项目常被迫走这条）；另有个别模块只给 GPL，用了会传染。选型阶段就要逐模块确认，细节见 核心机制篇 §1 与 工程化篇 。"},{"a":"s2","h":"没有 Qt 会怎样","x":"02 没有 Qt 会怎样 理解一个框架，先看它替你挡掉了什么 假设不用任何框架，要在三个平台上开出一个能显示按钮的窗口。你会面对三套 思路相似、细节完全不同 的原生 API： 平台 窗口与消息 语言 / 特点 控件 Windows CreateWindowEx + GetMessage / DispatchMessage 消息循环 + WndProc 回调 C API，字符串 UTF-16（ wchar_t ） 系统自带一批（Common Controls），风格随系统版本变 Linux (X11/Wayland) XCB/Wayland 协议事件 + 自己写事件循环（ poll 连接 fd） C API，字符串 UTF-8 系统不提供控件 ，按钮、输入框都要自己画、自己处理键盘与输入法 macOS NSApplication + NSRunLoop + 委托对象 Objective-C / Swift，需要混编 Cocoa 控件，但 API 风格与前两者毫无相似 共同点是三者都遵循 「事件循环 + 回调」 这个 GUI 编程的普适模型；差异在于 API、字符编码、坐标与 DPI 规则、剪贴板、输入法、字体渲染、线程约束。Qt 把这些差异关进了一层插件里： 你的代码：QPushButton / connect / QTcpSocket 一份源码，三个平台通用 Qt 公共 API（Core / Gui / Widgets / Network …） 语义在所有平台上保持一致 QPA — Qt Platform Abstraction（平台插件层） windows · xcb · wayland · cocoa · eglfs · linuxfb · offscreen Win32 / DirectWrite GetMessage 消息循环 HWND / WndProc X11 / Wayland XCB 事件 + poll(fd) 控件全靠自绘 Cocoa NSApplication NSRunLoop / 委托 QPA 是「一份代码跑三个平台」的关键：换平台只是换一个插件，上面两层不动 这张图不是纯理论，它直接对应一个部署阶段人人都会遇到的报错： This application failed to start because no Qt platform plugin could be initialized 。含义就是最下面那层插件（Windows 上是 plugins/platforms/qwindows.dll ，Linux 上是 libqxcb.so ）没有随程序一起拷过去。把 exe 单独复制到另一台机器就跑不起来，根因即此，解法见 工程化与部署篇 。 除了窗口，Qt 还统一了这些日常琐事 问题 不用框架时 Qt 的答案 中文乱码 Windows 是 UTF-16、Linux 是 UTF-8，编码转换到处写 QString 内部统一 UTF-16，边界处 toUtf8() / fromUtf8() 显式转换 路径分隔符 \\ 与 / 分头处理 API 内部一律 / ， QDir::toNativeSeparators() 只在给外部程序时用 配置存储 Windows 注册表、macOS plist、Linux 配置文件各写一遍 QSettings 一套 API，后端自动映射 多语言 自己搞一套字符串表 tr(\"开始\") + Qt Linguist 的 .ts / .qm 流程 高 DPI 缩放 各平台缩放模型不同，界面在 4K 屏上或糊或小 Qt 6 默认开启高 DPI 缩放，逻辑像素与物理像素分离 定时器与异步 IO 平台各自的 timer / select / IOCP QTimer 、 QTcpSocket 等统一挂在同一个事件循环上 换个角度说， Qt 的价值 =「跨平台一致性」+「补齐 C++ 缺失的运行时能力」+「一个成熟的控件与工具生态」 。这三点也解释了它的代价：你必须接受它的对象模型和线程规则，而这套规则正是本系列后面四篇要讲透的东西。"},{"a":"s3","h":"真实应用场景与产品","x":"03 真实应用场景与产品 谁在用它，为什么非它不可 六类主战场 场景 典型形态 为什么落到 Qt 工业上位机 PLC / 运动控制 / 产线监控 / 测试台软件 要直接调厂商的 C/C++ SDK（采集卡、运动控制卡、相机），换语言就得多封一层；开发在 Windows、设备端常是 Linux 机器视觉与检测 缺陷检测、尺寸测量、读码 算法侧是 OpenCV / Halcon / 相机 SDK（全是 C++）；图像高频刷新对带 GC 的语言不友好 科学仪器与医疗设备 示波器、色谱、超声、DR 影像工作站 设备生命周期 10 年以上，需要长期可维护 + LTS 版本；常同时有嵌入式面板和 PC 端软件 车机与座舱 HMI 仪表盘、中控、大屏 Qt Quick 的 GPU 动效 + 嵌入式无窗口系统直跑（eglfs）；工具链成熟，设计师可参与 专业创作 / EDA / CAD 3D 软件、影视后期、芯片设计工具 核心是重型 C++ 计算，界面需要大量自定义控件与插件化扩展 跨平台桌面工具 播放器、下载器、抓包与调试工具 一份代码发三平台，体积和内存都远小于 Web 方案 公开资料中可查到使用 Qt 的知名产品，能帮你建立「它到底能撑多大的软件」的直观印象： KDE Plasma 桌面环境（Qt 的发源地之一）、 VLC 、 OBS Studio 、 qBittorrent 、 Wireshark （Qt 界面）、 VirtualBox 管理界面、 Telegram Desktop （自研分支基于 Qt）、 Autodesk Maya 与 SideFX Houdini （其 Python 插件生态用的就是 PySide）、 DaVinci Resolve 、Linux 版 WPS Office 。 PySide6 / PyQt — Qt 的 Python 绑定。同一套 API 换成 Python 写，适合做内部工具、算法原型和自动化脚本界面。它和 C++ Qt 是 同一套对象模型与事件循环 ，所以本篇讲的概念在 Python 侧完全成立；差别只在打包部署和性能上限。 反过来说：什么时候不该选 Qt 这部分同样重要——用错工具比不用更贵。 情况 更合适的选择 理由 只发 Windows 的企业内部系统，团队是 C# 背景 WPF / WinUI 数据绑定与表单生态更顺手，招人也更容易 界面变化极快、团队全是前端 Electron / Tauri Web 技术栈迭代成本最低（代价是体积与内存） 算法调试面板、游戏内工具 Dear ImGui 几百行就能跑起来，无需构建步骤，随算法一起编译 本质是网页，只想套个壳 直接做 Web 不要为了「有个桌面版」引入一整套 C++ 框架 需要静态链接成单文件、又不能买商业许可 重新评估 LGPL 要求动态链接，这是合规硬约束，不是技术选择"},{"a":"s4","h":"关键模块地图","x":"04 关键模块地图 十几个模块，先只学两个 Qt 官方模块有几十个，新手看文档首页就懵。真实情况是： Qt Core 必修，UI 层二选一（Widgets 或 Quick），其余模块按需求现查现用 。 你的应用 业务逻辑 · 算法调用 · 设备封装 UI 层（二选一，也可混用） Qt Widgets 控件 / 布局 / 模型视图 CPU 绘制 · 桌面原生观感 Qt Quick / QML 声明式 UI / 动效 场景图 · GPU 合成 Qt Gui（底层，不是 Widgets） QPainter / QImage / 字体 窗口与输入事件的基础类型 按需模块 Network TCP/UDP/TLS/HTTP SerialPort / SerialBus 串口 · Modbus · CAN Sql / Concurrent SQLite · 并行计算 Charts / Test / DBus 曲线 · 单测 · Linux IPC Qt Core — 所有模块的地基（必修） QObject 对象树 · 信号槽 · 元对象(moc) · 事件循环 · 容器 / 字符串 / 文件 / 线程 / 定时器 无论选 Widgets 还是 QML，脚下都是同一套 Qt Core；先把地基学明白，上层皮肤是后话 模块速查表 模块 一句话 什么时候需要它 优先级 QtCore 对象模型、事件循环、容器、文件、线程、定时器 永远需要 必修 QtGui 绘图原语（ QPainter / QImage /字体）、窗口与输入的基础类型 自定义绘制、图像显示；用 Widgets 时它是隐含依赖 常用 QtWidgets 按钮、表格、对话框、布局、模型视图 做传统桌面 / 工业界面 主线之一 QtQuick + QtQml QML 声明式界面、动画、场景图 触摸屏、车机、动效丰富的 HMI 主线之一 QtNetwork QTcpSocket / QUdpSocket / TLS / QNetworkAccessManager 连设备、调 HTTP 接口、和后台通信 高 QtSerialPort 串口收发 仪器、传感器、单片机通信（工业几乎必用） 按需 QtSerialBus Modbus、CAN 总线 PLC、变频器、汽车总线 按需 QtConcurrent run / map / filter + QFuture 把批量计算丢进线程池，又不想手写线程 高 QtSql 数据库访问与 QSqlTableModel 本地 SQLite 存配方/日志；接 MySQL/PG 按需 QtCharts 折线、柱状、散点图 做曲线显示（ 注意许可：非商业授权下为 GPL ） 按需 QtTest 单元测试 + 模拟鼠标键盘 想给界面和逻辑写自动化测试 推荐 QtMultimedia 摄像头、音视频播放 预览摄像头、播放提示音 按需 QtDBus Linux 桌面 IPC 与系统服务 / 其他进程通信（仅 Linux） 按需 QtWebEngine 内嵌 Chromium 要在程序里显示网页或报表（ 体积暴涨上百 MB ） 慎用 ▶ 按场景挑模块 选一个场景，看看这类项目真正会链上哪些模块——你会发现清单比想象的短。 机器视觉检测台 串口仪器上位机 车机 / 触摸 HMI 跨平台桌面小工具 QtCore 地基，永远在 QtGui QtWidgets QtQuick / QML QtNetwork QtSerialPort QtSerialBus QtConcurrent QtSql QtCharts QtTest QtWebEngine 模块在构建脚本里的体现非常直白——需要哪个就 find_package 加一项、 target_link_libraries 连一项： # 一个视觉检测台大致就链这些 find_package(Qt6 REQUIRED COMPONENTS Widgets Network Concurrent SerialPort) target_link_libraries(inspector PRIVATE Qt6::Widgets Qt6::Network Qt6::Concurrent Qt6::SerialPort) Qt 5 与 Qt 6 的差异（强制 C++17、CMake 取代 qmake、 QList 改为连续存储、渲染走 RHI 抽象层）会影响老项目迁移，但不影响你入门。新项目 直接上 Qt 6 LTS ；差异清单见 核心机制篇 §2 。"},{"a":"s5","h":"第一个程序，逐行拆解","x":"05 第一个程序，逐行拆解 从 main() 到窗口出现在屏幕上 下面这 20 行是一个完整可运行的 Qt 程序：一个标签 + 一个按钮，点一次计数加一。 每一行都藏着一个 Qt 概念 ，我们逐个拆。 // main.cpp #include <QApplication> #include <QWidget> #include <QLabel> #include <QPushButton> #include <QVBoxLayout> int main( int argc, char * argv[]) { QApplication app(argc, argv); // ① 应用对象，必须最先建、放栈上 QWidget window; // ② 顶层窗口（没有 parent） window.setWindowTitle(QObject::tr( \"计数器\" )); // ③ tr() 为将来翻译留口子 auto * label = new QLabel( \"点击次数：0\" ); // ④ 堆上 new，但不写 delete auto * button = new QPushButton( \"点我\" ); auto * layout = new QVBoxLayout(&window); // ⑤ 布局，构造时即挂到 window layout->addWidget(label); // addWidget 会 setParent(window) layout->addWidget(button); int count = 0 ; QObject::connect(button, &QPushButton::clicked, // ⑥ 信号 → 槽（这里是 lambda） label, [label, count]() mutable { label->setText(QString( \"点击次数：%1\" ).arg(++count)); }); window.resize( 280 , 120 ); window.show(); // ⑦ 只是\"标记为可见\"，此刻还没画 return app.exec(); // ⑧ 进入事件循环，程序在这里\"活着\" } 八个要点 ① → QApplication 一个进程只能有一个，且必须在任何界面对象之前构造。 它在构造时加载 QPA 平台插件、初始化字体与样式、解析 -platform 等命令行参数。放在栈上是为了让它 最后才析构 （先于它析构的窗口才能正常清理）。纯后台程序（没界面）用 QCoreApplication ，只用 Qt Gui 不用 Widgets 时用 QGuiApplication 。 ② → 没有 parent 的 QWidget 就是顶层窗口 ，Qt 会向系统申请一个真实窗口；有 parent 的控件只是父窗口里的一块区域。「窗口」和「控件」在 Qt 里是同一个类，区别只在有没有父亲。 ③ → 所有给用户看的字符串都套 tr() 。现在没成本，将来要出英文版时，工具能自动扫出全部待翻译文本。事后补 tr() 是最没意义的加班之一。 ④⑤ → new 了却不 delete ，这不是内存泄漏 ： addWidget 内部会把控件的 parent 设为 window ； window 析构时会递归 delete 所有子对象。这就是 Qt 的 对象树 所有权模型。反过来， 如果你把控件建在栈上再交给布局，程序退出时会 double free ——父对象要 delete 一个栈地址。 ⑥ → connect 把「按钮被点击」这个信号接到一段代码上。 按钮完全不知道谁在监听，也不需要包含你的头文件——这就是解耦。第三个参数 label 是 context object ：它一析构，这条连接自动失效，避免野回调。 习惯：用 lambda 当槽时，总是传 context。 ⑦ → show() 不画界面。 它只设置可见标记并投递 QShowEvent / QPaintEvent 到事件队列。真正的绘制发生在 exec() 之后、事件循环取出 paint 事件时。所以经典新手现象是： show() 后面紧跟一个耗时循环 → 窗口是一片空白甚至假死 。 ⑧ → exec() 才是程序的主循环 ，概念上就是 while (!quit) { 取一个事件; 分发给目标对象; } 。它一直不返回，直到 quit() /最后一个窗口关闭；返回值成为进程退出码。 所有槽函数、定时器、网络回调都是被这个循环调用的 ——它们跑在同一个线程、排在同一条队上。 QApplication app 加载平台插件 建对象 / connect 纯内存操作 show() 投递 Show/Paint 事件 app.exec() 进入事件循环，不再返回 事件循环内部（单线程，逐个处理） 取出一个事件 分发给目标对象 执行 paintEvent 或你的槽函数 槽里耗时不返回 = 界面冻结 事件来源： 鼠标 / 键盘 定时器 socket 可读 跨线程信号 整个 GUI 程序就是这一个循环。理解「谁在调用我的槽」，是理解 Qt 的第一个台阶 ▶ 亲眼看「界面冻结」 下面的转圈由 JS 逐帧驱动，等价于「界面重绘」。点第一个按钮：本页主线程被同步占住 1.5 秒——和 Qt 里「槽函数里做耗时计算」 完全同一种病 ，转圈会明显停住、刷新率掉到 0。点第二个按钮：同样 1.5 秒的工作量被切片交还给事件循环，转圈全程流畅。 状态：空闲 刷新率：-- fps ❌ 在\"槽\"里死算 1.5 秒 ✅ 切片 / 丢给工作线程 这是 Qt 的第一条铁律：界面对象只能在主线程创建和访问，槽函数必须尽快返回。 耗时的事情交给工作线程或切片调度（ QTimer::singleShot(0, ...) ），完成后用信号把结果送回主线程。 不要 用 QApplication::processEvents() 硬撑着刷新界面——它会在你的调用栈中间重新分发事件，导致槽函数重入甚至 this 被删除后继续访问。原理与替代方案见 线程与并发篇 。"},{"a":"s6","h":"构建链：moc / uic / rcc","x":"06 构建链：moc / uic / rcc Qt 项目多出来的三个代码生成器 Qt 项目的编译过程比普通 C++ 项目多一步：在编译器动手之前，先有三个工具扫过你的源码， 生成额外的 .cpp/.h 一起参与编译 。不知道它们存在，就会被一类奇怪的报错困住。 工具 输入 输出 解决什么 moc Meta-Object Compiler 含 Q_OBJECT 宏的头文件 moc_xxx.cpp C++ 没有反射。moc 生成类的元信息表、信号函数的实现体、以及「按索引调用某个成员函数」的分派代码，信号槽才能在运行时工作 uic UI Compiler Qt Designer 拖出来的 xxx.ui （XML） ui_xxx.h 把可视化设计的界面翻译成「一堆 new 控件 + 设置属性 + 布局」的 C++ 代码 rcc Resource Compiler xxx.qrc 清单 + 图标/qss/翻译文件 qrc_xxx.cpp 把资源文件 编进可执行文件 ，用 \":/icons/play.png\" 访问，发布时不用带一堆散图 mainwindow.h (Q_OBJECT) mainwindow.ui res.qrc mainwindow.cpp / main.cpp moc uic rcc moc_mainwindow.cpp ui_mainwindow.h qrc_res.cpp 编译 + 链接 你的 exe （资源已内嵌） CMake 的 AUTOMOC / AUTOUIC / AUTORCC 会自动调用这三个工具 三个生成器的产物和你的 .cpp 一起编译；CMake 打开 AUTO* 开关后全程自动，无需手写规则 最小 CMake 工程 # CMakeLists.txt cmake_minimum_required(VERSION 3.19) project(counter LANGUAGES CXX) find_package(Qt6 REQUIRED COMPONENTS Widgets) qt_standard_project_setup() # Qt 6.3+：自动打开 AUTOMOC / AUTOUIC 等常用开关 qt_add_executable(counter main.cpp mainwindow.cpp mainwindow.h # 头文件也要列出来，AUTOMOC 才会扫到它 mainwindow.ui # .ui 交给 AUTOUIC ) target_link_libraries(counter PRIVATE Qt6::Widgets) qt_add_resources(counter \"res\" PREFIX \"/\" FILES icons/play.png) 配置时如果报「找不到 Qt6」，是因为 CMake 不知道 Qt 装在哪。传一个前缀即可： cmake -B build -DCMAKE_PREFIX_PATH=D:/Qt/6.8.0/msvc2022_64 。用 Qt Creator 打开工程时它会自动带上这个参数，这也是新手推荐用 Qt Creator 起步的原因之一。 三个「一看就懂根因」的经典报错 报错 根因 解法 undefined reference to vtable for MyClass 类里写了 Q_OBJECT 但 moc 没为它生成代码（头文件没进源码列表 / 加宏后没重新配置构建） 把头文件加入 qt_add_executable ；重新跑 CMake，必要时清一次构建目录 自定义信号 undefined reference 信号只有声明—— 它的函数体本来就该由 moc 生成 ，你却漏了 Q_OBJECT 补上 Q_OBJECT （必须在类体第一行区域，且类必须直接或间接继承 QObject ） 在 .cpp 里定义带 Q_OBJECT 的类，链接失败 AUTOMOC 对 .cpp 内的类生成 xxx.moc ，但需要你自己包含它 在该 .cpp 末尾加 #include \"xxx.moc\" 看到「 vtable 」「 no such signal 」这类词就条件反射想到 moc，能省掉入门期最多的无效搜索。moc 究竟生成了什么代码、 emit 展开后长什么样，在 核心机制篇 §4 有逐行反汇编级别的拆解。"},{"a":"s7","h":"五大核心概念速览","x":"07 五大核心概念速览 先建立正确直觉，深水区留给后面四篇 下面五个概念构成了「会写 Qt」的最小知识集。每个给一句话定义、一个类比、一段最小代码，以及新手最容易在这里犯的错。 7.1 对象树：谁负责 delete 每个 QObject 可以有一个 parent 和任意多个 children。 parent 析构时会自动 delete 全部 children ，递归向下。GUI 里一个窗口动辄几十上百个控件，这套机制把「逐个管理生命周期」变成了「管好根节点」。 像公司的组织架构：部门撤销时，下属岗位一并撤销，不需要 HR 逐个发通知。但如果某个岗位 同时挂在两个部门下 （对象树 + shared_ptr 双重所有权），撤销时就会有两边都来「清理」同一个人的荒诞场面——这正是 double free。 ❌ 栈对象交给对象树 QWidget window; QLabel label( \"hi\" ); layout->addWidget(&label); // parent = window // window 析构时 delete 一个栈地址 → 崩溃 ✅ 堆对象 + 明确的 parent QWidget window; auto * label = new QLabel( \"hi\" ); layout->addWidget(label); // 树接管所有权 // 不写 delete；需要弱引用时用 QPointer 7.2 信号槽：对象之间怎么通话 信号 = 「某件事发生了」的声明（ 只有声明，实现由 moc 生成 ）；槽 = 一个普通成员函数或 lambda。 connect 把两者接起来，双方都不需要认识对方的类型。 class Device : public QObject { Q_OBJECT // 必写：moc 的标记 public : void poll() { emit valueChanged(readSensor()); } signals : void valueChanged( double v); // 无函数体 }; // 连接：函数指针语法，编译期检查签名 connect(device, &Device::valueChanged, gauge, &Gauge::setValue); // 一个信号可连多个槽；接收者析构时连接自动断开 信号槽的三个高价值特性，也是它相对裸回调的意义： ① 一对多、运行时可增删； ② 接收者析构自动断连，不会留野指针回调； ③ 跨线程时自动切换执行线程 ——工作线程 emit ，主线程的槽照样安全地在主线程执行。代价是需要继承 QObject 、引入 moc 步骤，单次调用比直接函数调用慢几十纳秒（热路径按帧按像素的循环里别用）。 7.3 事件循环：程序的心跳 鼠标键盘、重绘请求、定时器到期、socket 可读、跨线程信号，最终都变成 事件 排进同一个队列，由 exec() 里的循环逐个取出分发。 一个线程一个事件循环 （要跑 exec() 才有）。 QTimer — 挂在事件循环上的定时器。 QTimer::singleShot(0, obj, func) 是一个很实用的技巧：把一段代码「推到下一轮循环再执行」，用来切分长任务、或者避免在信号处理中直接销毁自己。同理， deleteLater() 也是投递一个删除事件—— 它依赖事件循环，没有循环的线程里对象永远不会被删 。 7.4 布局系统：不要写死坐标 Qt 用布局管理器（ QVBoxLayout / QHBoxLayout / QGridLayout / QFormLayout ）自动计算控件几何。控件通过 sizeHint 报告理想尺寸、通过 sizePolicy 声明伸缩意愿，布局据此分配空间。 新手常用 setGeometry(10, 20, 80, 24) 手摆坐标，在自己机器上看着挺好，然后在三个地方崩塌： ① 用户拉伸窗口，控件不动； ② 换 4K 高 DPI 屏，一切错位； ③ 界面翻译成德语，按钮文字被截断。布局系统正是为这三件事存在的—— 只在自定义绘制的画布里才该谈像素坐标 。 7.5 模型 / 视图：数据多了必须换写法 Qt 提供两套路子显示列表和表格： 便捷类 （ QTableWidget / QListWidget ，逐个 item 塞数据）和 模型视图 （自己实现 QAbstractTableModel ，视图按需向模型取数）。 QTableWidget（便捷类） QTableView + 自定义 Model 数据存在哪 控件内部，每格一个 QTableWidgetItem 对象 你自己的容器（ std::vector 都行），视图不持有数据 1 万行 × 10 列 10 万个堆对象，构造慢、内存高 只为 可见的几十行 调用 data() 适合 配置页那种几十行的固定表 日志、采集数据、数据库结果集 代价 — 要实现 rowCount / columnCount / data / headerData ，增删要正确发 beginInsertRows 等信号 判断标准很简单： 数据行数由外部输入决定（可能上万）就用模型视图 ，否则用便捷类省事。大数据量表格与图像显示的性能细节在 工程化篇 。 还有两个「早知道早省事」的小机制 资源系统（qrc） ：图标、样式表、翻译文件通过 .qrc 编进 exe，用 \":/icons/play.png\" 这样的路径访问。避免了「换台机器图标全丢」。 样式表（QSS） ：类 CSS 的语法调整控件外观， QPushButton:hover { background: #2d6cdf; } 。适合做主题；但大量复杂 QSS 会拖慢绘制，且与原生观感冲突，工业软件里通常只做克制的定制。"},{"a":"s8","h":"实战：采集 → 显示架构","x":"08 实战：采集 → 显示架构 一个真实小项目该怎么分层 需求 — 一台设备通过 TCP（或串口）以 100 Hz 上报数据帧；界面要实时画曲线、显示连接状态、支持开始/停止记录，记录写入本地文件；断线要自动重连。这几乎是所有工业上位机的最小骨架。 新手最常见的写法是：把 socket 建在 MainWindow 里， readyRead 槽里解析数据、更新曲线、顺手写文件。 能跑，但三个月后没人敢改 ：界面代码里混着协议解析和文件 IO，写盘一卡界面就掉帧，换成串口要重写一遍，想加个自动化测试无从下手。 正确的做法是按 职责 切开，用信号槽做层间唯一的通信方式： UI 层 · 主线程 MainWindow ChartPanel（曲线） StatusBar / 控制按钮 业务层 · 主线程（无界面依赖） AcquisitionController（状态机 / 重连策略） RingBuffer（最近 N 点，供 UI 定时取用） 设备层 · 工作线程 A DeviceLink（抽象接口） TcpLink SerialLink 存储层 · 工作线程 B Recorder（批量写盘 / 轮转） 攒够 N 帧或 200 ms 才落盘一次 写盘阻塞不影响采集与界面 状态 / 数据（信号） start / stop frameReady（Queued） frameReady（Queued） 四层三线程：界面只关心「显示什么」，设备层只关心「怎么收字节」，中间靠信号解耦 线程怎么分 组件 线程 为什么 所有界面对象 必须主线程 Qt 的硬约束，别的线程碰界面就是未定义行为 AcquisitionController 主线程 它只做状态机和转发，几乎不耗时；放主线程省掉一堆同步问题 TcpLink / SerialLink 工作线程 A 协议解析、大包拼接可能耗时；且它内部有自己的事件循环处理 socket 事件 Recorder 工作线程 B 磁盘 IO 会不定时卡住几十毫秒，绝不能挡住采集或界面 把对象搬到工作线程的标准装配代码——注意注释里的三个坑： // AcquisitionController::start() m_thread = new QThread( this ); m_link = new TcpLink; // ① 不能给它 parent，否则 moveToThread 失败 m_link->moveToThread(m_thread); // 线程启动后，在新线程里执行 open() connect(m_thread, &QThread::started, m_link, &TcpLink::open); // 数据回传：跨线程，Qt 自动用 Queued 连接（参数会被拷贝） connect(m_link, &DeviceLink::frameReady, this , &AcquisitionController::onFrame); connect(m_link, &DeviceLink::stateChanged, this , &AcquisitionController::onState); // ② 退出顺序：先删对象，再让线程结束，最后删线程 connect(m_thread, &QThread::finished, m_link, &QObject::deleteLater); m_thread->start(); // ③ 这里之后就不要再直接调 m_link 的普通函数了 // 要触发它做事，一律通过信号或 QMetaObject::invokeMethod 数据帧用值类型跨线程传 — struct Frame { qint64 tsNs; QVector<double> ch; }; 配 Q_DECLARE_METATYPE(Frame) + 启动时 qRegisterMetaType<Frame>() 。 不要传裸指针 ：接收方不知道谁负责释放，也无法保证发送方不在同时改它。 QVector 是写时复制的，按值传的成本比想象中低；100 Hz 这个量级完全不用担心拷贝开销。忘了注册元类型的症状很隐蔽—— 槽静默不执行 ，只有一行控制台 warning。 UI 刷新必须与数据速率解耦 100 Hz 的数据不代表要 100 Hz 重绘界面。人眼看不出 30 Hz 以上的差别，而每帧都触发一次曲线重绘会把主线程吃光。 ❌ 每帧直接更新界面 void ChartPanel::onFrame( const Frame& f) { m_series->append(f.tsNs, f.ch[ 0 ]); m_label->setText(fmt(f)); chart()->update(); // 每 10 ms 一次全量重绘 } // 数据越快界面越卡；点数无上限，内存持续涨 ✅ 环形缓冲 + 定时合并刷新 // 采集侧：只写缓冲，不碰界面 void ChartPanel::onFrame( const Frame& f) { m_ring.push(f); } // 构造时启动一个 33 ms 定时器 connect(&m_timer, &QTimer::timeout, this , [ this ]{ if (m_ring.empty()) return ; m_series->replace(m_ring.snapshot()); // 一次性换整条曲线 m_label->setText(fmt(m_ring.back())); }); m_timer.start( 33 ); // ≈30 fps，与数据速率无关 建议的目录结构 src/ main.cpp ui/ mainwindow.{h,cpp,ui} chartpanel.{h,cpp} // 只做显示与交互 core/ acquisition_controller.{h,cpp} frame.h ring_buffer.h device/ device_link.h tcp_link.{h,cpp} serial_link.{h,cpp} storage/ recorder.{h,cpp} CMakeLists.txt tests/ test_protocol.cpp // 协议解析可以脱离界面单独测 这套分层的实际收益，在需求变化时才显现： 换成串口 → 只加一个 SerialLink 实现 DeviceLink 接口，上面三层不动； 加录制格式 → 只改 Recorder ； 要写自动化测试 → 协议解析和状态机都不依赖 UI，可以直接喂字节流断言输出； 要做无界面的采集服务 → 去掉 ui 层，换 QCoreApplication 就能跑。判断分层是否成功有个简单标准： 业务层与设备层的代码里不应该出现任何 QWidget 头文件 。 其中的每个环节都有更深的坑：TCP 的粘包半包与重连状态机在 网络与 IPC 篇 ， moveToThread 的线程亲和性与死锁案例在 线程与并发篇 。"},{"a":"s9","h":"Widgets 还是 QML","x":"09 Widgets 还是 QML 入门期唯一必须做的选型 两套 UI 技术共存在同一个框架里，是 Qt 让新人最困惑的地方。它们不是新旧关系，而是 面向不同场景 ，且都在持续维护。 Qt Widgets Qt Quick / QML 怎么写 纯 C++（可配 Designer 拖界面） QML 声明式脚本 + C++ 后端，两种语言 渲染 CPU 绘制（ QPainter ） 场景图 + GPU 合成 ，独立渲染线程 观感 贴近系统原生 自定义外观，跨平台一致 擅长 控件密集的表单、大表格、多窗口 / 多文档、菜单与快捷键、无障碍 动画转场、手势触摸、非矩形与自由布局、多分辨率适配 不擅长 复杂动效写起来啰嗦 密集表格与复杂桌面交互要自己造轮子；C++ 与 QML 边界容易失控 硬件要求 低，虚拟机 / 远程桌面都稳 依赖 GPU 与驱动 一个真实的工程坑 ：QML 默认需要可用的 GPU 加速。而工业现场大量存在「集显工控机 + 远程桌面（RDP/VNC）运维」的组合——这种环境下 QML 可能退化到软件渲染（ QT_QUICK_BACKEND=software ）后严重掉帧，甚至因驱动问题起不来。 如果你的软件要靠远程桌面运维，这一条几乎可以直接定下选 Widgets。 三句话判断 做 桌面工具 / 工业上位机 、界面以表单表格为主、团队是 C++ 背景、要跑在杂七杂八的工控机上 → Widgets 。 做 触摸屏 / 车机 / 消费级产品 HMI 、有设计师参与、要动效和多分辨率、硬件 GPU 有保障 → QML 。 两者 可以混用 ：Widgets 主框架里用 QQuickWidget 嵌一块 QML 做仪表盘或动效区，是常见的折中。但混用会同时承担两套心智负担，除非确有需要。 本系列后续四篇讲的都是 Qt Core 层 的机制——对象树、信号槽、线程、事件循环、网络。 这些内容对 Widgets 和 QML 完全通用 ，所以你不必先纠结选型再开始学。选型的更细致对比（含性能与团队协作角度）在 工程化篇 。"},{"a":"s10","h":"新手十二坑 · 学习顺序","x":"10 新手十二坑 · 学习顺序 按症状查根因 这十二条覆盖了绝大多数 Qt 入门期的「莫名其妙」。建议扫一遍留个印象，真遇到时能直接对上。 # 症状 根因 正解 1 程序退出时崩溃 栈上的控件被交给了布局 / 设了 parent，父对象去 delete 栈地址 交给对象树的控件一律 new ；顶层窗口可以放栈上 2 控制台： Cannot move object with a parent 给准备 moveToThread 的对象设了 parent 工作对象不设 parent，用 deleteLater 管理生命周期 3 继承 QThread ，但槽还是卡界面 QThread 对象本身属于创建它的线程 ，它的槽默认在原线程执行；只有 run() 里的代码在新线程 用「普通 QObject + moveToThread 」，不要继承 QThread 4 点了按钮界面就假死、变白 槽函数里长时间不返回，事件循环停转 耗时任务挪线程，或用 QTimer::singleShot(0,…) 切片 5 加了 processEvents() 后偶发崩溃 事件在调用栈中间被重新分发 → 槽重入、 this 已被删 不用它；必须用时配 QPointer 守卫 + 禁用输入事件 6 工作线程里更新界面，随机崩溃 界面对象只允许主线程访问 线程里 emit 信号，让主线程的槽去改界面 7 跨线程信号「不触发」，程序不崩 参数是自定义类型且未注册元类型，事件被静默丢弃 Q_DECLARE_METATYPE + qRegisterMetaType ；用 qInstallMessageHandler 把 Qt warning 收进日志 8 undefined reference to vtable 漏写 Q_OBJECT ，或加了宏后 moc 没重跑 补宏、把头文件列进构建目标、必要时清构建目录 9 .cpp 里定义的 QObject 类链接不过 AUTOMOC 生成了 xxx.moc 但没人包含 该 .cpp 末尾 #include \"xxx.moc\" 10 TCP 收到的数据时多时少、解析错乱 把 readyRead 当成「一帧到齐」，忽略了粘包 / 半包 累积到缓冲区，按「长度前缀 / 定界符」循环切帧，并校验长度上限 11 换 4K 屏或翻译后界面错位、文字截断 写死像素坐标与固定宽度 一律用布局；宽度靠 sizePolicy 与 minimumSizeHint 12 exe 拷到别的机器起不来 缺 Qt 运行库与 平台插件 （ platforms/qwindows.dll ） 用 windeployqt / linuxdeployqt 打包；把「干净虚拟机启动测试」列入发布清单 建议的学习顺序 第 1 步 → 装 Qt Creator （自带调试器与 Designer，最省事的起点），照 §5 敲一遍计数器，再用 Designer 拖一个界面感受 uic。目标：能独立建工程、能打断点。 第 2 步 → 读 Qt 核心机制 ：对象树、信号槽与 moc、事件循环。这是全系列的地基，也是面试主战场。 第 3 步 → 读 线程与并发 ，然后动手把 §5 的计数器改成「后台线程算 1000 万次求和 + 进度条」。目标： moveToThread 装配代码能自己写出来。 第 4 步 → 读 网络与本机 IPC ，实现 §8 那个采集显示小项目（可以先用一个假的数据源模拟 100 Hz）。目标：粘包处理与重连状态机。 第 5 步 → 读 工程化与陷阱 ，把项目用 CMake 组织好、打包到一台干净机器上跑起来。目标：能交付，不只是能跑。 完整的时间安排与阶段检查点见 桌面 GUI 学习路径 。"},{"a":"s11","h":"面试题集（12 道）","x":"11 面试题集（12 道） 入门层面最常被问到的那些"},{"a":"s11-1","h":"11.1 基础（必答）","x":"11.1 基础（必答） 点击每道题展开参考答案（先自测，再对照）。 基础 Qt 是一个 GUI 库吗？Qt Core 和 Qt Widgets 是什么关系？ 不准确。Qt 是 跨平台应用框架 ，GUI 只是其中一部分。它由三层组成：跨平台基础设施（字符串、容器、文件、线程、网络、国际化）、自建运行时（元对象系统、信号槽、属性）、UI 工具箱（Widgets 与 Quick）。 QtCore 是 地基 ，提供 QObject 、对象树、信号槽、事件循环，不含任何界面类； QtWidgets 建立在 QtCore + QtGui 之上，提供控件与布局。所以写一个没有界面的命令行工具或服务，也完全可以只用 QtCore （配 QCoreApplication ）。 延伸 三个 Application 类的区别： QCoreApplication （无界面）→ QGuiApplication （用 Qt Gui / QML）→ QApplication （用 Widgets）。选错会在运行时报缺少某些初始化。 基础 main() 里 show() 之后为什么必须 app.exec() ？ exec() 到底在做什么？ show() 并不绘制窗口，它只是设置可见标记并 投递 Show / Paint 事件到事件队列。 exec() 进入事件循环，概念上是 while (!quit) { 取事件; 分发; } ——只有循环转起来，那些事件才会被取出执行，窗口才真正画出来。 不调 exec() 的话， main 直接返回、对象析构、进程退出，用户可能只看到窗口闪一下或什么都看不到。 exec() 的返回值是退出码，通常由 QApplication::quit() 或最后一个窗口关闭触发返回。 追问 「exec 之前 emit 的跨线程信号会丢吗？」不会。Queued 连接是把调用打包成事件入队， exec() 开始后会照序执行。反之， 一个不跑事件循环的线程里，Queued 信号和 deleteLater() 永远不会被处理 。 基础 Qt 里的控件是谁负责 delete 的？为什么 new 了不写 delete 不算泄漏？ parent 负责 。每个 QObject 有一个 parent 和一组 children，parent 析构时递归 delete 所有 children。把控件 addWidget 给布局、或构造时传入 parent，所有权就交给了这棵对象树，因此不写 delete 是正确写法。 两个必须记住的边界： ① 交给对象树的对象必须是堆对象——栈对象会导致父类去 delete 栈地址； ② 不要和 shared_ptr 混用，那等于两套所有权同时释放。需要「对象死后指针自动置空」时用 QPointer 。 基础 为什么在槽函数里做耗时计算会让界面卡死？正确做法是什么？ 因为重绘、鼠标、键盘事件都排在 主线程同一个事件队列 里，靠事件循环逐个取出分发；槽函数是被这个循环 同步调用 的。槽不返回，循环就取不到下一个事件，重绘请求得不到处理，界面就是冻住的（系统还可能标记为「无响应」）。 正确做法：耗时工作交给工作线程（ QObject + moveToThread ，或 QtConcurrent::run ），用信号回传进度与结果；或者把长任务切成小块，用 QTimer::singleShot(0, …) 分片，让每片之间回到事件循环。 反面教材 用 processEvents() 强行刷新界面。它在当前调用栈中间重新分发事件，会导致槽重入、容器迭代器失效，甚至用户关窗口后 this 已释放却继续被访问。"},{"a":"s11-2","h":"11.2 中级（区分熟练度）","x":"11.2 中级（区分熟练度） 中级 moc 是什么？为什么 C++ 需要它，它在构建流程的哪一步？ moc （Meta-Object Compiler）是一个 代码生成器 。它在编译 之前 扫描带 Q_OBJECT 宏的头文件，生成 moc_xxx.cpp ，内容包括：类的元信息表（类名、信号槽签名、属性）、 信号函数的实现体 、以及一个能「按索引调用某个成员函数」的静态分派函数。 需要它的根本原因是 C++ 没有反射 ： connect 要在运行时把一个信号和一个槽关联起来、跨线程时还要按索引找到函数并传参，标准 C++ 做不到。Qt 选择用代码生成补上这个能力，而不是靠宏黑魔法或运行时解析。 流程位置 CMake 打开 AUTOMOC 后：moc / uic / rcc 先跑，产物与你的 .cpp 一起进编译。所以 undefined reference to vtable 、自定义信号「未定义」这类链接错误，通常不是代码逻辑问题，而是 moc 没跑到这个类 。 中级 新项目该选 Qt Widgets 还是 Qt Quick / QML？说出你的判据。 不是新旧之争，而是场景之分。 Widgets ：纯 C++、CPU 绘制、贴近原生观感，擅长控件密集的表单、大表格、多窗口、菜单快捷键与无障碍，对硬件要求低。 QML ：声明式 + GPU 场景图，擅长动效、手势触摸、自由布局与多分辨率适配，设计师可参与。 工业上位机 / 桌面工具 + C++ 团队 + 杂牌工控机 → Widgets。 车机 / 消费级触摸 HMI + 有 GPU 保障 + 有设计资源 → QML。 可混用（ QQuickWidget 嵌一块动效区），但要承担两套心智负担。 现场经验 如果软件要靠 远程桌面运维 或跑在集显工控机上，QML 可能退化为软件渲染而严重掉帧——这一条常常直接决定选 Widgets。 中级 程序在别人机器上报「could not load the Qt platform plugin」，怎么排？这反映了什么设计？ 它反映的是 QPA（Qt Platform Abstraction） 这层设计：Qt 把 Win32 / XCB / Wayland / Cocoa / eglfs 的差异关进 平台插件 ，同一份上层代码换平台只换插件。代价是插件必须随程序一起部署，且路径要能被找到。 确认目标目录下有 platforms/qwindows.dll （Linux 为 platforms/libqxcb.so ）——用 windeployqt / linuxdeployqt 打包，而不是手工拷 dll。 用 QT_DEBUG_PLUGINS=1 启动，日志会打印它尝试了哪些路径、为什么加载失败。 Linux 上常见是插件本身缺依赖（ ldd libqxcb.so 看缺哪个 so），而不是插件不存在。 发布流程里必须包含 干净机器 / 干净容器的启动测试 ，开发机永远测不出这类问题。 中级 一个 100 Hz 数据采集的界面，如何保证曲线不掉帧？ 核心思路是 把「数据速率」和「刷新速率」解耦 ，三件事： 采集不碰界面 ：设备层在工作线程收包解析，通过 Queued 信号把 值类型 的数据帧送到主线程（自定义类型记得注册元类型）。 写入环形缓冲 ：主线程的槽只把数据放进固定容量的环形缓冲，不触发重绘；这样点数有上限，内存不会无限涨。 定时合并刷新 ：用一个 30 fps 左右的 QTimer 一次性取快照、整体替换曲线数据。数据再快，重绘频率不变。 配套 磁盘记录放独立线程并批量落盘（攒够 N 帧或 200 ms 写一次），避免 IO 抖动传导到采集与界面。大数据量表格同理：用模型视图按需取数，而不是把几万行塞进 QTableWidget 。"},{"a":"s11-3","h":"11.3 高级（体现深度）","x":"11.3 高级（体现深度） 高级 跨线程发信号时，参数是怎么传到另一个线程的槽里的？ 跨线程连接（Auto 判定为 Queued）时， emit 并不会直接调用槽，而是：把每个参数 深拷贝 一份、连同「要调用哪个槽」的索引打包成一个 QMetaCallEvent ， postEvent 到 接收者所在线程 的事件队列；等那个线程的事件循环取出该事件，才执行真正的槽调用。 拷贝参数需要 Qt 知道该类型如何构造 / 拷贝 / 析构，这靠元类型系统。自定义类型没 Q_DECLARE_METATYPE + qRegisterMetaType 时，Qt 只打一行 warning 然后 静默丢弃这次调用 ——槽不执行、程序不崩，是最难查的一类问题。 两个推论 ① AutoConnection 的方向判定发生在 emit 时刻 （比较当前线程与接收者线程），不是 connect 时刻，所以 moveToThread 后已有连接会自动改变行为；② 接收者线程若没有事件循环，Queued 信号永远不会执行。 高级 Qt 的事件循环底层用的是什么多路复用机制？这对架构选择意味着什么？ 是 poll(2) ，不是 epoll——Qt 自带的 QEventDispatcherUNIX 用 poll ，桌面 Linux 默认的 GLib 派发器底层同样是 poll 。因此 Qt 的 IO 多路复用复杂度是 O(n) 于 fd 数量 ：每轮都把整个 fd 数组交给内核，返回后线性扫描。 这对客户端场景完全够用（fd 少、事件类型杂：GUI + 定时器 + socket 混在一起，还要与窗口系统集成）；但 不适合上万连接的服务端 ，会在 poll 上烧掉大量 CPU。 架构结论 如果一个 Qt 应用确实要扛大量连接，常见做法是把网络层独立出来用 epoll / io_uring / Asio 实现，只通过 Queued 信号把结果送回 UI 线程；界面与高并发 IO 各用擅长的机制，而不是勉强让事件循环兼任。 高级 Qt 的 LGPL 许可会怎样影响架构与交付方式？ LGPLv3 允许闭源商业产品使用 Qt，但要求 动态链接 ，并让终端用户能够替换 Qt 库（提供必要的链接材料与说明）。这带来几个实际约束： 不能静态链接成单文件 。嵌入式固件、想「一个 exe 走天下」的诉求会与之冲突——那条路要买商业许可。 交付物必须包含 Qt 动态库与平台插件，部署体积和打包流程都要按此设计（并写进发布清单）。 对 Qt 源码做了修改（打补丁）时，修改部分需按 LGPL 要求提供。 逐模块确认许可 ：个别模块在开源渠道下只给 GPL（历史上 Qt Charts 就是典型），一旦链上就会传染到整个产品。 工程习惯 把「依赖清单 + 每个依赖的许可」纳入 CI 检查，升级 Qt 大版本时重新核对一次（Qt 6 拆分了部分模块的归属）。合规问题发现得越晚，代价越高。 高级 要显示一张 10 万行的日志表格，怎么做到不卡？ 关键是 不要让控件持有数据 ： 放弃 QTableWidget （每格一个堆对象，10 万行 × 10 列 = 百万对象，构造慢、内存爆）；改用 QTableView + 自己实现的 QAbstractTableModel ，数据留在你自己的容器里。 视图只对 可见区域 调用 data() ，滚动到哪取哪； data() 里不要做格式化以外的重活（更不要查数据库）。 数据来自远端或数据库时用 canFetchMore / fetchMore 分页增量加载，而不是一次性拉全。 批量增删务必配对发出 beginInsertRows / endInsertRows ；漏发或错发行号会让视图与模型不一致，表现为空白行或崩溃。 刷新要合并：高频追加日志时先入缓冲，定时（如 100 ms）批量插入一次，避免每条都触发一轮布局与重绘。 再往深一层 如果列宽是自适应的，视图可能为了算宽度去遍历 所有行 ，此时行数一大立刻卡住——解法是固定列宽或只按可见行采样（ setResizeContentsPrecision ）。这类「模型视图的隐藏 O(n)」在工程化篇有更完整的清单。 ➡️ Qt 核心机制（下一篇） 🧵 Qt 线程与并发 🔌 Qt 网络与本机 IPC 🧰 Qt 工程化与陷阱 🗺️ 学习路径 📚 目录 🏠 主页 Qt 零基础全景入门 — 是什么 · 解决什么问题 · 真实应用 · 关键模块 · 第一个程序 · 项目分层 — Kavin Tech Notes · 2026 ↑"}]},{"u":"desktop-gui/qt_threading.html","t":"Qt 并发与跨线程完全指南","c":"桌面 GUI / Qt","s":[{"a":"","h":"","x":"Qt 并发与跨线程完全指南 · QThread / moveToThread / QtConcurrent / 线程亲和性 / 死锁排查 Kavin Tech Notes ← 主页 目录 25 min ◐ Qt 并发与跨线程 QThread 不是线程 两种用法与官方推荐 线程亲和性与跨线程信号槽 QtConcurrent 与 QFuture 同步原语：Qt vs 标准库 GUI 线程铁律 与 std::thread 混用 死锁与卡顿案例集 面试题集（12 道） 9.1 基础 9.2 中级 9.3 高级 Desktop GUI · Qt Concurrency · 2026 Qt 并发与跨线程完全指南 Qt 多线程的坑几乎全部来自同一个误解： 把 QThread 当成「线程」 。它其实是「线程的遥控器」，自己住在创建它的线程里。理解了这一点， moveToThread 为什么是推荐写法 、 为什么子类化后槽跑在了主线程 、 为什么 deleteLater 会泄漏 ，全部迎刃而解。本篇从对象的线程归属讲起，一路到 QtConcurrent、GUI 线程铁律与死锁排查。 核心难度 ★★★★★ 面试出现率 极高 阅读时长 ~25 min 前置 Qt 核心机制 · std::thread QThread · moveToThread 线程亲和性 QtConcurrent · QFuture 死锁排查 没写过 Qt？ 先读 Qt 零基础全景入门 建立全景，再读 Qt 核心机制 打好对象树与信号槽的地基——本篇默认你已经知道「事件循环是什么」。"},{"a":"s1","h":"QThread 不是线程","x":"01 QThread 不是线程 纠正这一个误解，八成的坑就没了 QThread ：一个 管理 操作系统线程的 QObject。 start() 创建 OS 线程并在其中执行 run() ；但 QThread 对象本身仍然属于创建它的那个线程 （通常是主线程）。所以它的槽函数、它的 deleteLater ，默认都在主线程执行。 把 QThread 想成 工地的对讲机 ，不是工人本身。你在办公室（主线程）拿着对讲机，按下 start() 把工人派出去干活。 对讲机一直在你手上 ——你对着它说话（调它的槽），声音是在办公室里响的，不是在工地上。想让工人听见，得通过 无线电 （跨线程信号槽）传过去。 主线程（GUI 线程） 新建的 OS 线程 QThread 对象 th thread() == 主线程 · 槽在主线程跑 th->start() 创建 OS 线程，令其执行 run() th->quit() / th->wait() 在主线程调用，控制对面的循环 QThread::run() 默认实现就是 exec() —— 起事件循环 Worker 对象（moveToThread 过来的） thread() == 新线程 · 槽在这里跑 该线程的事件队列 接收 Queued 信号 / 定时器 / DeferredDelete 左边是遥控器，右边是工地。QThread 对象在左，run() 与 Worker 在右 这个区分直接解释了三个常见困惑： 「我在 QThread 子类里加了槽，为什么它在主线程执行？」 ——因为槽属于 QThread 对象，而对象住在主线程。只有 run() 的函数体在新线程。 「为什么推荐 moveToThread？」 ——因为要让「干活的对象」住到新线程去，而不是让「遥控器」去干活。 「为什么我的 worker 收不到信号？」 ——多半是 run() 被重写后没调 exec() ，那个线程压根没有事件循环，Queued 信号无处投递。"},{"a":"s2","h":"两种用法与官方推荐","x":"02 两种用法与官方推荐 moveToThread 为主，子类化为辅 写法 A：moveToThread（推荐，适合事件驱动型任务） class Worker : public QObject { Q_OBJECT public slots : void process( const QString& path) { // 在工作线程执行 for ( int i = 0 ; i <= 100 ; ++i) { if (m_abort.loadRelaxed()) { emit canceled(); return ; } heavyStep(i); emit progress(i); // 自动 Queued 回主线程 } emit finished(); } void abort() { m_abort.storeRelaxed( 1 ); } // 注意：这个槽也在工作线程排队 signals : void progress( int ); void finished(); void canceled(); private : QAtomicInt m_abort{ 0 }; }; // —— 装配（在主线程）—— auto * th = new QThread( this ); auto * w = new Worker; // ⚠️ 必须无 parent，否则 moveToThread 失败 w->moveToThread(th); connect(th, &QThread::started, w, &Worker::process); connect(w, &Worker::progress, this , &MainWindow::onProgress); connect(w, &Worker::finished, th, &QThread::quit); // 停事件循环 connect(w, &Worker::finished, w, &QObject::deleteLater); // 删 worker connect(th, &QThread::finished, th, &QObject::deleteLater); // 删 thread 对象 th->start(); 那四条 connect 的顺序不是随便写的，而是一条严格的关闭链 ： finished → 让线程的事件循环退出（ quit ）； finished → worker 自删（此时它还在工作线程，DeferredDelete 会在事件循环退出前被处理）； QThread::finished （线程真正结束时发出，在主线程投递）→ 删 QThread 对象。少任何一条都会泄漏，顺序反了会崩。 moveToThread 有两条硬约束 ： ① 对象 不能有 parent ，否则调用失败并打印 Cannot move objects with a parent ——因为对象树必须整体属于同一线程； ② 只能 「推」不能「拉」 ，即必须在对象 当前所属线程 里调用 moveToThread （把自己推出去），不能从别的线程把它拽过来。移动时该对象的所有 children 会跟着一起走。 写法 B：子类化 QThread（适合一条道跑到黑的计算任务） class ScanThread : public QThread { Q_OBJECT protected : void run() override { // 这里面才是新线程 while (!isInterruptionRequested()) { Frame f = camera.grabBlocking(); // 阻塞式循环，不需要事件循环 emit frameReady(f); // emit 可以跨线程 } // 若这里不调 exec()，本线程就没有事件循环： // · 本线程内创建的 QObject 收不到 Queued 信号 // · QTimer 不会触发 // · deleteLater() 永远不执行 → 泄漏 } signals : void frameReady(Frame); }; moveToThread（写法 A） 子类化 run()（写法 B） 适合 事件驱动 ：要接收多种请求、可随时调度新任务 单一长任务 ：阻塞式采集循环、纯计算 事件循环 默认有（ run() 的默认实现就是 exec() ） 你不调 exec() 就没有 能否接收 Queued 信号 能 不调 exec 则不能 常见错误 忘了「worker 不能有 parent」 误以为子类的槽在新线程 （其实在主线程） 取消机制 原子标志位 / requestInterruption requestInterruption + isInterruptionRequested 被问「QThread 的两种用法哪个更好」时， 不要答「官方推荐 moveToThread 所以用它」 。正确回答是分场景： 需要事件循环、要能随时接新任务的用 moveToThread；只是把一段阻塞循环搬到后台、不需要接收消息的，子类化 run() 反而更直白 。真正的红线只有一条—— 不要给 QThread 子类加槽然后以为它在新线程执行 。 线程的销毁：必须 quit + wait // ❌ 直接析构还在跑的线程 // QThread: Destroyed while thread is still running // → Qt 随后调用 terminate()，线程在任意位置被打断： // 锁不释放、析构不执行、缓冲区写一半 → 数据损坏或死锁 // ✅ 标准关闭序列 MainWindow::~MainWindow() { if (m_thread && m_thread->isRunning()) { m_thread->requestInterruption(); // 通知业务循环退出 m_thread->quit(); // 让事件循环 exec() 返回 if (!m_thread->wait( 3000 )) // 给一个上限，别无限等 qWarning() << \"worker thread did not exit in 3s\" ; } } quit() 只让 事件循环 退出，对「 run() 里在跑 while 循环」的子类化线程 毫无作用 ——那种情况必须靠 requestInterruption() 或自己的原子标志位。 terminate() 在任何情况下都不该出现在生产代码里，它是最后的止损手段，不是关闭手段。"},{"a":"s3","h":"线程亲和性与跨线程信号槽","x":"03 线程亲和性与跨线程信号槽 「这个对象属于哪个线程」是 Qt 多线程的中心问题 线程亲和性（Thread Affinity） ：每个 QObject 都记录自己「属于」哪个线程，可用 obj->thread() 查询。默认是 创建它的那个线程 。这个归属决定了三件事：它的槽在哪执行（Queued 时）、它的定时器在哪计时、它的 deleteLater 由谁处理。 跨线程调用的三种正确姿势 // ① 信号槽（首选）——自动 Queued，参数深拷贝 connect(worker, &Worker::progress, this , &MainWindow::onProgress); // ② invokeMethod 传 lambda（Qt5.10+）——把一段代码扔到目标对象所属线程执行 QMetaObject::invokeMethod(worker, [worker, path]{ worker->process(path); // 在 worker 所属线程运行 }, Qt::QueuedConnection); // ③ 需要返回值时用 BlockingQueued（谨慎） int result = 0 ; QMetaObject::invokeMethod(worker, \"compute\" , Qt::BlockingQueuedConnection, Q_RETURN_ARG( int , result), Q_ARG( int , 42 )); // ⚠️ 调用方会阻塞；若 worker 与调用方同线程 → 立即死锁 ❌ 直接调另一个线程对象的方法 // 主线程里： worker->process(path); // 这是普通函数调用，会在【主线程】执行！ // 结果：① UI 照样卡死 // ② 同时 worker 内部状态被两个线程碰 → race // 变体：worker 里 new 一个 QTimer void Worker::setup() { m_timer = new QTimer( this ); m_timer->start( 100 ); } // 若 setup() 是在主线程直接调的， // timer 归主线程，永远不会在工作线程触发 ✅ 经由信号 / invokeMethod QMetaObject::invokeMethod(worker, [worker, path]{ worker->process(path); // 工作线程执行 }, Qt::QueuedConnection); // 需要在工作线程里创建对象，就在工作线程里创建： connect(th, &QThread::started, worker, [worker]{ worker->setup(); // 此时已在工作线程 }); // 断言归属，把问题挡在开发期 void Worker::process( const QString& p) { Q_ASSERT(QThread::currentThread() == this ->thread()); ... } 给每个 worker 的入口槽加一句 Q_ASSERT(QThread::currentThread() == thread()) ，成本几乎为零，却能在 debug 构建里立刻抓出「以为是跨线程、其实是直接调用」的错误。同理，UI 侧的关键函数可以加 Q_ASSERT(QThread::currentThread() == qApp->thread()) 。 QTimer 的线程规则 定时器 必须在拥有它的线程里 start() ，否则 Qt 报 Timers can only be used with threads started with QThread 或者干脆不触发。 定时器精度依赖 该线程事件循环的响应速度 。如果那个线程正在执行一个耗时槽，定时器就会延迟——所以 QTimer 在负载高时不是硬实时的，做心跳/超时判断要用 时间戳比较 而不是「回调次数 × 间隔」。 QTimer::singleShot(0, obj, ...) 是「让出一次事件循环、下一轮再执行」的惯用法，常用于把长任务切片，避免 processEvents 的重入风险。"},{"a":"s4","h":"QtConcurrent 与 QFuture","x":"04 QtConcurrent 与 QFuture 不需要事件循环的那一半：任务并行 QThread 解决的是「把一个长期运行的角色搬到后台」； QtConcurrent 解决的是「把一批短任务并行跑完」。两者是不同的抽象层次，不要互相替代。 // ① 跑一个任务，拿 future QFuture< int > f = QtConcurrent::run([]{ return heavyCompute(); }); // ② 数据并行：对容器每个元素并行处理 QList<QImage> imgs = load(); QFuture< void > g = QtConcurrent::map(imgs, [](QImage& im){ denoise(im); }); // ③ map-reduce QFuture< int > total = QtConcurrent::mappedReduced(files, countDefects, sumUp); // ④ Qt6：continuation，不阻塞 UI 线程 QtConcurrent::run([]{ return inspect(); }) .then(qApp, [](Result r){ showResult(r); }); // then 的 context 决定回调线程 // ⑤ 进度反馈 + 取消（Qt6 的 QPromise） QFuture< void > job = QtConcurrent::run([](QPromise< void >& promise){ promise.setProgressRange( 0 , 100 ); for ( int i = 0 ; i <= 100 ; ++i) { if (promise.isCanceled()) return ; // 协作式取消 step(i); promise.setProgressValue(i); } }); QFutureWatcher< void >* watcher = new QFutureWatcher< void >( this ); connect(watcher, &QFutureWatcherBase::progressValueChanged, ui->bar, &QProgressBar::setValue); // 自动回到 UI 线程 watcher->setFuture(job); 不要在 QtConcurrent::run 里做阻塞等待。 它默认用 全局线程池 （ QThreadPool::globalInstance() ），线程数约等于 CPU 核数。如果池里的任务互相等待（任务 A 等任务 B 的结果，而 B 还排在队列里），池被占满就 整体死锁 ——现象是程序不崩不报错，只是永远卡住。做法：阻塞型 IO 用独立的 QThreadPool （ setMaxThreadCount 调大），或者用 QThread + 事件循环；计算型才交给全局池。 需求 推荐工具 理由 长期后台角色（相机采集、串口收发、后台服务） QThread + moveToThread 需要常驻 + 事件循环接收指令 一批独立短任务（批量图像处理） QtConcurrent::map 自动利用多核，写法最短 一次性的耗时计算，要拿结果 QtConcurrent::run().then() continuation 风格，不阻塞 UI 需要进度条与取消 QPromise + QFutureWatcher 进度信号自动回到 UI 线程 自定义线程池策略（优先级、限流） QThreadPool + QRunnable 可控性最高 纯计算、与 Qt 无关的库代码 std::thread / std::async 不引入 Qt 依赖，便于单测 QFuture::waitForFinished() 在 UI 线程调用 = 界面卡死，和直接同步执行没有区别。要么用 QFutureWatcher 的信号，要么用 Qt6 的 .then() 。这是「用了异步框架但写成了同步」的典型反例，和 C++ 多线程编程模式 里 std::future::get() 的坑是同一个。"},{"a":"s5","h":"同步原语：Qt vs 标准库","x":"05 同步原语：Qt vs 标准库 现在该用哪一套 Qt 标准库对应 今天该用哪个 QMutex / QRecursiveMutex std::mutex / std::recursive_mutex 标准库 （除非要 tryLock(ms) 这种带超时的接口） QMutexLocker std::lock_guard / std::unique_lock 标准库 QReadWriteLock std::shared_mutex 标准库 QWaitCondition std::condition_variable 标准库 QSemaphore std::counting_semaphore （C++20） 看编译器支持 QAtomicInt / QAtomicPointer std::atomic<T> 标准库 ，内存序语义更清晰 信号槽 Queued （无对应） Qt ——这是 Qt 真正不可替代的部分 QThreadStorage thread_local 标准库 结论很清楚： C++11 之后，Qt 的同步原语已经没有技术优势 ，它们存在只是历史原因（Qt4 时代标准库还没有线程）。新代码用标准库，语义与内存序更精确、可移植、便于单元测试。 唯独跨线程信号槽和事件循环没有标准替代品 ——那才是 Qt 并发模型的价值所在。内存序细节见 C++ 内存模型详解 。 一个例外值得注意： Qt 的隐式共享容器（ QString 、 QByteArray 、 QImage 、Qt6 的 QList ）内部用原子引用计数，「拷贝到别的线程」是安全的，但「两个线程同时操作同一个实例」不安全 。跨线程传大对象时靠这个 COW 特性可以避免深拷贝——但一旦有一方调用非 const 方法触发分离（detach），语义就变了。传值给信号槽是安全用法；共享一个成员变量再各自改，不是。"},{"a":"s6","h":"GUI 线程铁律","x":"06 GUI 线程铁律 工业检测项目里最实用的一节 只有主线程能碰 QWidget 及其派生类。 这不是「建议」，是 Qt 的硬性约束——窗口系统的句柄、绘制后端、样式引擎都不是线程安全的。在工作线程里调 label->setText() 可能表现为：偶发花屏、断言失败、随机崩溃，甚至在开发机上「看起来一直没问题」而在客户现场每天崩一次。 哪些图形类可以在工作线程用 类 工作线程可用？ 说明 QImage 可以 纯内存位图，后端无关。 图像算法应该全程用它 QPainter 绘到 QImage 可以 离屏渲染在工作线程完全合法 QPixmap 不可以 可能是窗口系统的资源（X11 Pixmap / GDI 对象） QWidget 及派生 不可以 包括 setText 、 update 、 show 一切操作 QFont / QColor / QPen 可以 纯值类型 QML 的 QQuickItem 不可以 但 Quick 的 渲染 本身在独立的渲染线程 工业检测的典型流水线 ：采集线程从相机 SDK 拿到裸数据 → 包成 QImage （零拷贝构造，指定 stride）→ 算法线程用 OpenCV/Halcon 处理，结果仍然是 QImage + 一组缺陷框 → 通过 Queued 信号把 QImage 传回 UI 线程 （QImage 是隐式共享，跨线程传递只加引用计数）→ UI 线程再 QPixmap::fromImage() 并显示。 QPixmap 的转换必须放在最后一步、在 UI 线程做 ，这是这条流水线唯一容易搞错的地方。 动手感受：主线程被占住 vs 交给工作线程 下面的转圈图标由浏览器主线程驱动，等价于 Qt 的 GUI 线程。点第一个按钮会用忙等占住主线程 1.5 秒——转圈会 整个冻住 ；点第二个按钮任务同样耗时，但被切片交还了事件循环，转圈保持流畅。 idle 在主线程里死算 1.5 秒 切片调度（模拟工作线程） 复位 UI 更新的频率控制 把工作线程的每一帧结果都 emit 回 UI，会出现一个反直觉的问题： 信号的产生速度超过 UI 的消费速度时，事件队列会无限增长 ——内存持续上涨，界面反而越来越卡（因为它在处理几秒钟以前的旧帧）。 限频 ：UI 侧用一个 QTimer （比如 30 Hz）主动去取「最新一帧」，工作线程只更新一个受锁保护的「最新结果」变量，不发信号。这是显示类场景的标准做法。 背压 ：工作线程发之前检查一个原子计数，UI 处理完再减；超过阈值就丢弃中间帧。 合并 ：进度类信号用「变化超过 1% 才 emit」，避免每次循环都发。 「工作线程算得比 UI 画得快，怎么办」是个很能体现工程经验的问题。答 「加锁保护最新结果 + UI 定时拉取」 比答「用队列缓冲」更好——后者只是把无界增长推迟了。这本质上是 背压与过载保护 问题在 GUI 场景的具体形态。"},{"a":"s7","h":"与 std::thread 混用","x":"07 与 std::thread 混用 现实项目里两套一定会共存 算法库、第三方 SDK、公司自己的基础库，往往用的是 std::thread / std::async ，不可能全改成 QThread。好消息是 两者可以共存 ，需要注意的只有几点。 // ① std::thread 里 emit 信号 —— 可以，但目标对象必须有事件循环 std::thread t([this]{ auto r = thirdPartySdk::run(); // this 属于主线程 → 自动 Queued，安全 emit resultReady(r); }); t.detach(); // ⚠️ detach 之后无法等待，析构顺序不可控，慎用 // ② 更安全：不 emit，用 invokeMethod 显式指定目标 std::thread t2([this]{ auto r = thirdPartySdk::run(); QMetaObject::invokeMethod( this , [ this , r]{ onResult(r); }, Qt::QueuedConnection); }); // ③ 不要在非 Qt 线程里 new QObject 然后指望它有事件循环 // Qt 会用 QAdoptedThread 包装这个线程，QThread::currentThread() 可用， // 但它没有 exec()，所以该线程内的 QObject 收不到 Queued 信号。 场景 选择 理由 需要接收 Qt 信号 / 用 QTimer / deleteLater QThread 必须有 Qt 事件循环 纯计算、无 Qt 交互、想做单元测试 std::thread / std::jthread 不引入 Qt 依赖 需要 stop_token 式协作取消 std::jthread （C++20） Qt 侧只有 requestInterruption ，粒度更粗 要跨线程返回值 + 异常传播 std::future 或 QFuture 信号槽 不能传异常 ，只能传错误码/消息 信号槽不能跨线程传播 C++ 异常。 在槽里抛出的异常如果穿过事件循环，Qt 的行为是未定义的（Qt6 会直接 std::terminate ）。所以工作线程的槽 必须自己 catch 住所有异常 ，转成一个 errorOccurred(int code, QString msg) 信号发出去。这与 std::future 能自动搬运 exception_ptr 形成鲜明对比——需要异常语义时应该用 future，见 跨线程异常传递 。"},{"a":"s8","h":"死锁与卡顿案例集","x":"08 死锁与卡顿案例集 按现场出现频率排序 ① 自己阻塞自己（同线程） 主线程：emit sig (Blocking) 等待槽执行完 槽也在主线程，排在队列里 但主线程正在等，取不出事件 永久互等 ② 双向 Blocking（跨线程） 线程 A 线程 B A 阻塞等 B 的槽；B 的槽里又 Blocking 调回 A 的槽 → 环 BlockingQueuedConnection 的两种典型死锁：同线程自锁、跨线程成环 # 症状 根因 处理 1 点某个按钮后整个程序卡死 BlockingQueuedConnection 的收发双方在同一线程 改 Queued；确实要返回值就重构成「请求 + 回调信号」 2 程序退出时崩溃 / 卡住不退 QThread 析构时线程还在跑，被 terminate requestInterruption + quit + wait(timeout) 3 worker 的槽从不执行 子类化 run() 没调 exec() ，或对象没 moveToThread 核对 worker->thread() ；补 exec() 4 内存持续上涨，界面越来越卡 信号产生快于消费，事件队列无界增长 限频 / 背压 / 合并（见 §6） 5 并行任务永久挂起，CPU 占用 0 QtConcurrent 全局池被阻塞任务占满 阻塞任务用独立池或 QThread 6 偶发花屏 / 随机崩溃 工作线程碰了 QWidget 或 QPixmap 只传 QImage，UI 线程再转 QPixmap 7 worker 泄漏，Valgrind 报 still reachable deleteLater 所在线程没有事件循环 补 exec() ，或改用普通 delete（确认无正在处理的事件） 8 数据偶尔算错，无法稳定复现 写死了 DirectConnection ，moveToThread 后成了跨线程直调 去掉硬编码的连接类型，交给 Auto；用 TSan 复检 排查工具链 ThreadSanitizer ：抓 data race 最有效，能直接指出「哪两个线程在哪两行访问了同一地址」。Qt 程序可以跑 TSan，注意屏蔽 Qt 内部的已知误报。用法见 Sanitizer 全家桶完全指南 。 GDB 多线程调试 ：卡死时 thread apply all bt 一次性打印所有线程栈，两个线程互相等在 QWaitCondition::wait 或 pthread_cond_wait 上就是死锁现场。见 GDB 多线程调试 与 死锁定位实战 。 Qt 自带的诊断 ： qputenv(\"QT_FATAL_WARNINGS\", \"1\") 让 Qt 的 warning 直接 abort，配合调试器能在「Cannot queue arguments」「Timers can only be used with…」发生的第一现场停下。 日志打线程 ID ： qSetMessagePattern(\"%{time} [%{threadid}] %{message}\") ，几乎零成本，却能让 80% 的线程问题一眼可见。"},{"a":"s9","h":"面试题集（12 道）","x":"09 面试题集（12 道） 按难度分层，先自测再对照"},{"a":"s9-1","h":"9.1 基础（必答）","x":"9.1 基础（必答） 点击每道题展开参考答案（先自测，再对照）。 基础 QThread 对象属于哪个线程？它的槽函数在哪个线程执行？ QThread 对象属于 创建它的线程 （通常是主线程），只有 run() 的函数体运行在新创建的 OS 线程里。 因此它的槽函数默认在 主线程 执行。这就是「给 QThread 子类加槽，以为它在后台跑」这个经典错误的根源。 记忆锚点 QThread 是「线程的遥控器」，不是线程本身。遥控器在你手上，工人在工地上。 基础 为什么不能在工作线程里直接操作 QWidget ？ 因为 Qt 的 GUI 层不是线程安全的：窗口句柄、绘制后端、样式引擎、布局系统都假设只有一个线程在访问；很多平台的窗口 API 本身也要求在创建窗口的线程调用。 违反的表现不一定是立刻崩溃，更常见的是 偶发花屏、断言失败、在客户现场每天崩一次 ——这才是它危险的地方。 正确做法 工作线程只处理数据（ QImage 可以在工作线程用），结果通过 Queued 信号发回主线程，由主线程更新界面。 基础 写出 moveToThread 的标准装配代码，并说明每条 connect 的作用。 auto * th = new QThread( this ); auto * w = new Worker; // 无 parent w->moveToThread(th); connect(th, &QThread::started, w, &Worker::process); connect(w, &Worker::finished, th, &QThread::quit); connect(w, &Worker::finished, w, &QObject::deleteLater); connect(th, &QThread::finished, th, &QObject::deleteLater); th->start(); started → process ：线程一起来就开工（此时已在工作线程）。 finished → quit ：活干完，让工作线程的事件循环退出。 finished → deleteLater （worker）：worker 自删，DeferredDelete 在事件循环退出前被处理。 QThread::finished → deleteLater （thread）：线程真正结束后，删掉 QThread 对象本身。 易错 worker 必须没有 parent ，否则 moveToThread 失败并打印 Cannot move objects with a parent 。 基础 Qt 的 QMutex 和标准库的 std::mutex ，新项目该用哪个？ 用 std::mutex 。Qt 的同步原语诞生于 C++11 之前，当时标准库还没有线程支持；今天它们相对标准库没有技术优势，反而带来 Qt 依赖，不利于把核心逻辑抽成可单测的纯 C++ 库。 唯一还值得用 Qt 版本的情况是需要 QMutex::tryLock(int timeout) 这类带超时的接口（C++ 里要用 std::timed_mutex ），或者代码库已经全用 Qt 风格、保持一致更重要。 真正不可替代的 Qt 并发模型的价值不在互斥量，而在 跨线程信号槽 + 事件循环 ——标准库至今没有对应物。"},{"a":"s9-2","h":"9.2 中级（区分熟练度）","x":"9.2 中级（区分熟练度） 中级 子类化 QThread 时如果不调 exec() ，会失去什么？ QThread::run() 的默认实现就是调用 exec() 启动事件循环。重写 run() 而不调 exec() ，这个线程就 没有事件循环 ，随之失去三样能力： 该线程内的 QObject 收不到 Queued 信号 （事件没人取）。 QTimer 不会触发 。 deleteLater() 投递的 DeferredDelete 事件永远不被处理 → 对象泄漏 。 这不一定是错——如果 run() 里就是一个「阻塞采集 → emit」的死循环，本来就不需要事件循环。关键是 知道自己放弃了什么 。 中级 quit() 、 terminate() 、 requestInterruption() 三者有什么区别？ quit() 请求 事件循环 退出（等价于 exit(0) ）。对「run() 里跑 while 循环、没有 exec()」的线程 完全无效 。 requestInterruption() 只是设置一个标志位，需要 run() 里主动用 isInterruptionRequested() 轮询。 协作式取消 ，安全。 terminate() 强杀线程，在任意指令处打断： 锁不释放、析构不执行、缓冲区可能写了一半 。生产代码里不应该出现。 标准关闭序列是三者配合： requestInterruption() （让业务循环退出）→ quit() （让事件循环退出）→ wait(timeout) （等它真的结束，并设上限）。 中级 工作线程算得比 UI 画得快，怎么处理？ 直接每帧 emit 会导致 事件队列无界增长 ：内存持续上涨，界面反而越来越卡，因为它在渲染几秒钟以前的旧帧。三种处理方式： 限频（首选） 工作线程只更新一个受锁保护的「最新结果」变量，不发信号；UI 侧用 30 Hz 的 QTimer 主动去拉。天然丢弃中间帧，队列长度恒定。 背压 用原子计数记录「已发未处理」数量，超阈值就跳过本次 emit。 合并 进度类信号加「变化超过 1% 才发」的门限，避免高频无意义更新。 「加个更大的队列缓冲」不是答案——它只是把无界增长推迟了，本质上是过载保护问题。 中级 QtConcurrent::run 里做阻塞 IO 有什么风险？ 它默认使用 全局线程池 ，线程数大约等于 CPU 核数。阻塞任务会长期占住池中的线程，导致两个后果： 吞吐塌陷 ：几个阻塞任务就把池占满，后面的计算任务全部排队。 整体死锁 ：如果池里的任务 A 在等待任务 B 的结果，而 B 还排在队列里等空闲线程——线程全被 A 这类任务占着，B 永远轮不到。现象是程序不崩不报错，CPU 占用 0，永久挂起。 正确做法 阻塞型 IO 用 独立的 QThreadPool （ setMaxThreadCount 按并发数调大）或者 QThread + 事件循环；全局池只留给 CPU 密集的短任务。这与标准库里「不要在 std::async 的默认策略下做阻塞等待」是同一类问题。"},{"a":"s9-3","h":"9.3 高级（体现深度）","x":"9.3 高级（体现深度） 高级 BlockingQueuedConnection 在什么情况下会死锁？为什么它仍然存在？ 两种死锁 ： 同线程使用 ：发送方阻塞等待槽执行，而槽的调用事件排在 同一个线程 的队列里——线程正在阻塞，取不出事件，永久互等。Qt 对这种情况会直接 qFatal ，但只在它能检测到时。 跨线程成环 ：A 阻塞等 B 的槽，B 的槽里又用 Blocking 调回 A 的槽。两边都在等对方，构成环。这种 Qt 检测不出来。 为什么保留它 ：有些场景确实需要「跨线程同步取值」，比如从工作线程读一个只有 UI 线程能提供的状态、或者在关闭流程中必须确认对方已经处理完。它是 把跨线程调用退化成同步调用 的逃生舱。 替代方案 优先重构成「请求信号 + 结果信号」的异步两段式，或者把需要的状态提前缓存成原子变量。真要同步取值时，至少确认调用链上不存在反向的 Blocking 调用。 高级 一个对象 moveToThread 之后，它此前建立的连接会发生什么变化？ 取决于连接类型： AutoConnection（默认） 自动适配 。因为 Auto 的判定发生在 emit 时刻——用 QThread::currentThread() 与 receiver->thread() 比较。对象换了线程，下次 emit 时判定结果就变了，无需重连。 写死的 DirectConnection 不会变 。moveToThread 之后，这条连接就成了「在发送方线程直接调用一个属于别的线程的对象的成员函数」——data race，而且是最难复现的那种：功能看起来正常，只是数据偶尔算错。 另外， 对象的 children 会跟着一起移动 ；它拥有的定时器会被重新注册到新线程（Qt 内部处理），但如果定时器是在旧线程 start() 的且移动时机不当，可能出现「定时器不再触发」。 工程结论 除非有明确理由， 不要手写连接类型 ，让 Auto 去判断。手写 Direct 的唯一合理场景是「明确要求同步执行且确信同线程」，并且要在代码旁写清楚为什么。 高级 Qt 信号槽能跨线程传播异常吗？如果不能，工作线程的错误该怎么上报？ 不能。 Queued 连接下，槽是由接收方线程的事件循环调用的，与 emit 方已经不在同一个调用栈上——异常没有地方可以传回去。异常如果穿过事件循环，Qt 的行为未定义，Qt6 下通常直接 std::terminate 。 正确做法 ：工作线程的每个入口槽都用 try-catch 包住，把异常转成错误信号： void Worker::process() { try { doWork(); emit finished(); } catch ( const std::exception& e) { emit errorOccurred(ErrCode::Internal, QString::fromUtf8(e.what())); } catch (...) { emit errorOccurred(ErrCode::Unknown, \"unknown exception\" ); } } 对比 std::future / QFuture 能自动搬运 std::exception_ptr ， get() 时在调用方重新抛出。 需要异常语义时应该选 future 而不是信号槽 ——这是两种并发模型的一个实质差异，不只是风格问题。 高级 设计一条工业相机的采集-处理-显示流水线，说明线程划分、对象归属与数据传递方式。 三线程划分 ： 采集线程 ：子类化 QThread ， run() 里是「阻塞等相机 SDK 回调 → 包装成 QImage 」的死循环。不需要事件循环，因为它只产出不接收。用 requestInterruption 停止。 处理线程 ： Worker + moveToThread ，需要事件循环，因为要接收「换算法参数」「暂停」等指令。算法全程操作 QImage （可以在非 UI 线程用），不碰 QPixmap。 UI 线程 ：只负责显示与交互，收到结果后 QPixmap::fromImage() 再画。 数据传递 ：帧数据用 QImage 经 Queued 信号传递——它是隐式共享的，跨线程「拷贝」只是原子加引用计数，不会深拷贝几十 MB 的像素。自定义的结果结构体（缺陷框列表等）需要 Q_DECLARE_METATYPE + qRegisterMetaType 。 背压 ：相机是恒定帧率的生产者，处理和显示都可能跟不上。采集→处理之间用有界队列，满了丢最旧帧（检测场景通常「最新的帧最有价值」）；处理→UI 之间用「最新结果变量 + UI 定时拉取」，不发高频信号。 关闭顺序 必须自上游向下游停：先停采集（ requestInterruption + wait ），再停处理（ quit + wait ），最后才析构 UI。反过来会出现「上游还在往已析构的下游发信号」——虽然 Qt 会在 receiver 析构时断开连接，但正在队列里的事件仍可能引用已释放的数据。 可观测性 三处埋点：采集帧率、处理耗时分布（p50/p99）、丢帧计数。没有这三个数，线上「偶尔卡一下」的问题无法定位。参见 C++ 可观测性完全指南 。 ⬅️ Qt 核心机制 ➡️ Qt 网络与本机 IPC 🧭 全景入门 🧵 C++ 多线程模式 📚 目录 🏠 主页 Qt 并发与跨线程完全指南 — QThread · moveToThread · QtConcurrent · 线程亲和性 — Kavin Tech Notes · 2026 ↑"}]}];
